AS $function$
  select coalesce((select string_agg(nullif(private.short_site(a->>'site'), '') || ' ' || private.min_label(a->>'start')
                            || case when coalesce(btrim(a->>'note'),'') <> '' then ' — ' || left(btrim(a->>'note'), 80) else '' end,
                            ' + ' order by case when a->>'start' ~ '^[0-9.]+$' then (a->>'start')::numeric end nulls last)
                     from jsonb_array_elements(case when jsonb_typeof(d->'assignments') = 'array' then d->'assignments' else '[]'::jsonb end) a
                    where coalesce(a->>'site','') <> ''),
                  nullif(private.short_site(d->>'site') || case when coalesce(d->>'time','') <> '' then ' ' || (d->>'time') else '' end, ''), '') $function$
CREATE OR REPLACE FUNCTION private.setup_link_new(p_who text, p_by text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare e jsonb; code text;
begin
  select data into e from public.records where coll='emps' and id=p_who and not deleted;
  if e is null or coalesce((e->>'inactive')::boolean,false) then raise exception 'no such person'; end if;
  if coalesce(e->>'role','') <> 'worker' then raise exception 'links are only for field workers'; end if;
  code := translate(encode(gen_random_bytes(18),'base64'),'+/=','-_');
  update private.setup_links set expires_at = least(expires_at, now()) where who=p_who and used_at is null;
  insert into private.setup_links(code_hash, who, made_by, expires_at) values (encode(digest(code,'sha256'),'hex'), p_who, p_by, now() + interval '7 days');
  return code;
end $function$
