CREATE OR REPLACE FUNCTION private.task_repeat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n jsonb := new.data; o jsonb := old.data; td date := (now() at time zone 'America/New_York')::date;
        base date; nd date; nid text; c jsonb; k text;
begin
  if jsonb_typeof(n) <> 'object' or jsonb_typeof(o) <> 'object' or new.deleted then return new; end if;
  if coalesce(o->>'status','') = 'done' and coalesce(n->>'status','') <> 'done' and coalesce(n->>'repNext','') <> '' then
    update records set deleted = true, updated_by = 'repeat', updated_at = now()
     where coll = 'jobs' and id = n->>'repNext' and not deleted and coalesce(data->>'status','') <> 'done'
       and not exists (select 1 from jsonb_object_keys(data) x where x like 'm\_%');
    new.data := n - 'repNext'; return new;
  end if;
  if coalesce(n->>'rep','') not in ('d','w','m') or coalesce(o->>'status','') = 'done' or coalesce(n->>'status','') <> 'done'
     or coalesce(n->>'repNext','') <> '' then return new; end if;
  base := case when coalesce(n->>'dueDate','') ~ '^\d{4}-\d{2}-\d{2}$' then (n->>'dueDate')::date else td end;
  if n->>'rep' = 'd' then nd := greatest(base, td) + 1; if extract(dow from nd) = 6 then nd := nd + 1; end if;
  elsif n->>'rep' = 'w' then nd := base + 7; while nd <= td loop nd := nd + 7; end loop;
  else nd := (base + interval '1 month')::date; while nd <= td loop nd := (nd + interval '1 month')::date; end loop; end if;
  c := n - array['status','doneAt','doneBy','chk','chkBy','chkAt','repNext','nudgeAt','nudgeBy','park','parkBy','photos','doneLinked','due'];
  for k in select x from jsonb_object_keys(c) x where x like 'done\_%' or x like 'seen\_%' or x like 'got\_%' or x like 'm\_%' loop c := c - k; end loop;
  nid := 'jr' || substr(md5(new.id || nd::text || clock_timestamp()::text), 1, 12);
  c := c || jsonb_build_object('id', nid, 'status', 'open', 'ts', (extract(epoch from now()) * 1000)::bigint, 'dueDate', to_char(nd, 'YYYY-MM-DD'),
                               'due', '', 'photo', false, 'repOf', coalesce(n->>'repOf', new.id));
  insert into records (coll, id, data, deleted, updated_by, updated_at) values ('jobs', nid, c, false, 'repeat', now());
  new.data := n || jsonb_build_object('repNext', nid);
  return new;
end $function$
