CREATE OR REPLACE FUNCTION private.travel_leg(p_who text, p_date text, p_kind text, p_site text, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rid text := 'tv' || p_kind || '_' || p_who || '_' || replace(p_date, '-', '');
        s jsonb; mi numeric; one numeric; thr numeric; rate numeric; blat numeric; blng numeric; dist numeric; n jsonb; nm text;
begin
  if p_on and p_site is not null then
    select r.data into s from public.records r where r.coll = 'sites' and r.id = p_site and not r.deleted;
  end if;
  if s is not null and jsonb_typeof(s) = 'object' then
    if jsonb_typeof(s->'trip') = 'object' and public._num(s->'trip'->>'mi') is not null and public._num(s->'trip'->>'min') is not null then
      mi := public._num(s->'trip'->>'mi'); one := round(public._num(s->'trip'->>'min'));
    elsif public._num(s->>'lat') is not null and public._num(s->>'lng') is not null then
      select public._num(data #>> '{}') into blat from public.records where coll = 'base' and id = 'lat' and not deleted;
      select public._num(data #>> '{}') into blng from public.records where coll = 'base' and id = 'lng' and not deleted;
      if blat is not null and blng is not null then
        dist := 3958.8 * 2 * asin(sqrt(power(sin(radians(public._num(s->>'lat') - blat) / 2), 2)
                + cos(radians(blat)) * cos(radians(public._num(s->>'lat'))) * power(sin(radians(public._num(s->>'lng') - blng) / 2), 2)));
        mi := dist * 1.25; one := round(mi / 0.55);
      end if;
    end if;
  end if;
  thr := coalesce((select coalesce(public._num(r.data->>'v'), public._num(r.data #>> '{}')) from public.records r
                   where r.coll = '_' and r.id = 'travelMi' and not r.deleted), 15);
  if mi is null or mi <= thr or one is null or one <= 0 then
    update public.records set deleted = true, updated_by = 'server', updated_at = now() where coll = 'travel' and id = rid and not deleted;
    return;
  end if;
  rate := (select public._num(r.data->>'rate') from public.records r where r.coll = 'rates' and r.id = p_who and not r.deleted);
  nm := coalesce(nullif(s->>'name', ''), p_site);
  n := jsonb_build_object('id', rid, 'who', p_who, 'site', p_site, 'date', p_date, 'kind', p_kind, 'auto', true, 'srv', true,
         'from', case when p_kind = 'to' then 'Office' else nm end, 'to', case when p_kind = 'to' then nm else 'Office' end,
         'miles', round(mi, 1)::float8, 'oneWay', one::float8,
         'minutes', round(one * (60 + case when p_date >= '2026-11-15' then 3.5 else 0 end) / 60, 2)::float8,
         'extraSec', case when p_date >= '2026-11-15' then 3.5 else 0 end,
         'pay', case when rate is null then null else round(rate * one * (60 + case when p_date >= '2026-11-15' then 3.5 else 0 end) / 3600, 2)::float8 end,
         'status', case when rate is null then 'norate' else 'approved' end);
  insert into public.records (coll, id, data, deleted, updated_by, updated_at) values ('travel', rid, n, false, 'server', now())
  on conflict (coll, id) do update set data = excluded.data || case when public.records.data ? 'fcSent' then jsonb_build_object('fcSent', public.records.data->'fcSent') else '{}'::jsonb end, deleted = false, updated_by = 'server', updated_at = now()
   where public.records.data is distinct from excluded.data or public.records.deleted;
end $function$
CREATE OR REPLACE FUNCTION private.travel_rebuild(p_who text, p_date text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f jsonb; l jsonb;
begin
  if p_who is null or p_date is null or p_date !~ '^\d{4}-\d{2}-\d{2}$' then return; end if;
  select x.data into f from public.records x
   where x.coll = 'punches' and not x.deleted and x.data->>'who' = p_who and (coalesce(x.data->>'src','') <> 'fingercheck' or public._num(x.data->>'in') >= 1793505600000)
     and coalesce(x.data->'voided','null'::jsonb) = 'null'::jsonb and not coalesce(x.data->'rejected' = 'true'::jsonb, false)
     and not coalesce(x.data->'pending' = 'true'::jsonb, false) and public._num(x.data->>'in') is not null
     and to_char(to_timestamp(public._num(x.data->>'in') / 1000.0) at time zone 'America/New_York', 'YYYY-MM-DD') = p_date
   order by public._num(x.data->>'in') asc limit 1;
  select x.data into l from public.records x
   where x.coll = 'punches' and not x.deleted and x.data->>'who' = p_who and (coalesce(x.data->>'src','') <> 'fingercheck' or public._num(x.data->>'in') >= 1793505600000)
     and coalesce(x.data->'voided','null'::jsonb) = 'null'::jsonb and not coalesce(x.data->'rejected' = 'true'::jsonb, false)
     and not coalesce(x.data->'pending' = 'true'::jsonb, false) and public._num(x.data->>'in') is not null
     and to_char(to_timestamp(public._num(x.data->>'in') / 1000.0) at time zone 'America/New_York', 'YYYY-MM-DD') = p_date
   order by public._num(x.data->>'in') desc limit 1;
  perform private.travel_leg(p_who, p_date, 'to', f->>'site', f is not null);
  perform private.travel_leg(p_who, p_date, 'home', l->>'site', l is not null and public._num(l->>'out') is not null);
end $function$
CREATE OR REPLACE FUNCTION private.trello_personal_tick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare base text; secret text;
begin
  if not exists (select 1 from public.server_config where k like 'trello\_user\_token:%') then return; end if;
  select v into base from public.server_config where k = 'functions_url';
  select v into secret from public.server_config where k = 'secret';
  if base is null or secret is null then return; end if;
  perform net.http_post(url := base || '/trello-personal', body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','x-push-secret', secret), timeout_milliseconds := 60000);
end $function$
CREATE OR REPLACE FUNCTION public._make_user(p_email text, p_pass text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare uid uuid; em text := lower(trim(p_email));
begin
  if not (public.is_boss() or public.no_team_yet()) then raise exception 'not allowed'; end if;
  perform public._pw_check(p_pass);
  select id into uid from auth.users where lower(email) = em;
  if uid is not null then
    if not public.no_team_yet() and not public.i_am_owner() and (public.signin_privileged(em) or public.emp_by_email(em) is null) then raise exception 'not allowed'; end if;
    update auth.users set encrypted_password = crypt(p_pass, gen_salt('bf')), email_confirmed_at = coalesce(email_confirmed_at, now()), updated_at = now() where id = uid;
    return uid;
  end if;
  uid := gen_random_uuid();
  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
                          created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change,
                          email_change_token_current, reauthentication_token, phone_change, phone_change_token)
  values ('00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated', em, crypt(p_pass, gen_salt('bf')), now(),
          '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now(), '', '', '', '', '', '', '', '');
  insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (gen_random_uuid(), uid, uid::text, jsonb_build_object('sub', uid::text, 'email', em, 'email_verified', true), 'email', now(), now(), now());
  return uid;
end $function$
CREATE OR REPLACE FUNCTION public._num(x text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select case when x ~ '^-?[0-9]+(\.[0-9]+)?$' then x::numeric end;
$function$
CREATE OR REPLACE FUNCTION public._pw_check(p text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare l text := lower(coalesce(p,''));
begin
  if length(coalesce(p,'')) < 8 then raise exception 'password too short'; end if;
  if p !~ '[A-Za-z]' or p !~ '[0-9]' then raise exception 'password needs letters and numbers'; end if;
  if l = any(array['password1','password123','qwerty123','abc12345','abcd1234','iloveyou1','admin123','welcome1','letmein1','monkey123','passw0rd','electrix1','electrix123','electrix2026','monsey123','spring123'])
     or l ~ 'electrix' or p ~ '^(.)\1+$' then raise exception 'password too common'; end if;
end $function$
CREATE OR REPLACE FUNCTION public._row_exists(c text, i text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.records r where r.coll = c and r.id = i
                 and coalesce(public.can_see2(r.coll, r.data, public.my_emp_data()), false));
$function$
CREATE OR REPLACE FUNCTION public.admin_create_user(p_email text, p_pass text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_boss() then raise exception 'not allowed'; end if;
  return public._make_user(p_email, p_pass);
end $function$
CREATE OR REPLACE FUNCTION public.admin_set_password(p_email text, p_pass text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare uid uuid;
begin
  if not public.is_boss() then raise exception 'not allowed'; end if;
  if not public.i_am_owner() and (public.signin_privileged(p_email) or public.emp_by_email(p_email) is null) then raise exception 'not allowed'; end if;
  perform public._pw_check(p_pass);
  update auth.users set encrypted_password = crypt(p_pass, gen_salt('bf')), updated_at = now()
  where lower(email) = lower(p_email) returning id into uid;
  return uid;
end $function$
CREATE OR REPLACE FUNCTION public.ai_key_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); m text; c text;
begin
  if not (me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll')) then raise exception 'not allowed' using errcode = '42501'; end if;
  select v into m from public.server_config where k = 'anthropic_key_meta';
  select v into c from public.server_config where k = 'ask_check';
  if not exists (select 1 from public.server_config where k = 'anthropic_key' and coalesce(v, '') <> '') then return null; end if;
  return coalesce(m::jsonb, '{}'::jsonb) || jsonb_build_object('check', case when c is null then null else c::jsonb end);
end $function$
CREATE OR REPLACE FUNCTION public.ai_set_key(p_v text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); v text := btrim(coalesce(p_v, ''));
begin
  if not (me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll')) then
    raise exception 'only the owner or Payroll can set the AI key' using errcode = '42501'; end if;
  if v = '' then delete from public.server_config where k in ('anthropic_key', 'anthropic_key_meta'); return null; end if;
  if length(v) > 300 or v ~ '\s' or v !~ '^sk-ant-' then raise exception 'that does not look like an Anthropic key (it starts with sk-ant-)' using errcode = '22023'; end if;
  insert into public.server_config (k, v) values ('anthropic_key', v) on conflict (k) do update set v = excluded.v;
  insert into public.server_config (k, v) values ('anthropic_key_meta', jsonb_build_object('last4', right(v, 4), 'at', now(), 'by', me->>'id')::text)
    on conflict (k) do update set v = excluded.v;
  return right(v, 4);
end $function$
CREATE OR REPLACE FUNCTION public.ai_take(p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare mine int; team int; month int; k text := coalesce(p_kind,'label');
begin
  if auth.uid() is null or not public.is_member() then return false; end if;
  if k = 'label' then
    perform pg_advisory_xact_lock(hashtext('ai_take'));
    select coalesce(sum(n),0) into team from ai_usage where day = current_date and kind = 'label';
    select coalesce(sum(n),0) into mine from ai_usage where day = current_date and kind = 'label' and uid = auth.uid();
    select coalesce(sum(n),0) into month from ai_usage where day >= date_trunc('month', current_date)::date and kind = 'label';
    if mine >= 60 or team >= 400 or month >= 3000 then return false; end if;
  elsif k = 'ask' then
    perform pg_advisory_xact_lock(hashtext('ai_take_ask'));
    select coalesce(sum(n),0) into team from ai_usage where day = current_date and kind = 'ask';
    select coalesce(sum(n),0) into mine from ai_usage where day = current_date and kind = 'ask' and uid = auth.uid();
    select coalesce(sum(n),0) into month from ai_usage where day >= date_trunc('month', current_date)::date and kind = 'ask';
    if mine >= 300 or team >= 1500 or month >= 15000 then return false; end if;
  end if;
  insert into ai_usage(day, uid, kind, n) values (current_date, auth.uid(), k, 1)
    on conflict (day, uid, kind) do update set n = ai_usage.n + 1;
  return true;
end $function$
CREATE OR REPLACE FUNCTION public.app_here(p_site text, p_at bigint, p_open boolean DEFAULT NULL::boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); v_who text := me->>'id'; nowms bigint := (extract(epoch from now())*1000)::bigint; h int; r text := '';
begin
  if v_who is null or p_at is null then return ''; end if;
  if p_at > nowms + 60000 or p_at < nowms - 15*60000 then return ''; end if;
  h := extract(hour from to_timestamp(p_at/1000.0) at time zone 'America/New_York')::int;
  if h < 6 or h >= 21 then return ''; end if;
  if p_site is not null and not exists (select 1 from records where coll='sites' and id = p_site and not deleted) then p_site := null; end if;
  insert into private.app_seen(who, site, at, open, updated) values (v_who, p_site, p_at, p_open, now())
    on conflict (who) do update set site = excluded.site, at = excluded.at, open = excluded.open, updated = now()
    where private.app_seen.at <= excluded.at;
  if p_site is not null then r := private.back_on_job(v_who, p_site, p_at, 'his phone'); end if;
  return coalesce(r, '');
end $function$
CREATE OR REPLACE FUNCTION public.app_here2(p_site text, p_at bigint, p_open boolean DEFAULT NULL::boolean, p_sched boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); v_who text := me->>'id'; nowms bigint := (extract(epoch from now())*1000)::bigint; h int; r text := '';
begin
  if v_who is null or p_at is null then return ''; end if;
  if p_at > nowms + 60000 or p_at < nowms - 15*60000 then return ''; end if;
  h := extract(hour from to_timestamp(p_at/1000.0) at time zone 'America/New_York')::int;
  if h < 6 or h >= 21 then return ''; end if;
  if p_site is not null and not exists (select 1 from records where coll='sites' and id = p_site and not deleted) then p_site := null; end if;
  insert into private.app_seen(who, site, at, open, updated) values (v_who, p_site, p_at, p_open, now())
    on conflict (who) do update set site = excluded.site, at = excluded.at, open = excluded.open, updated = now()
    where private.app_seen.at <= excluded.at;
  if p_site is not null then
    r := private.back_on_job(v_who, p_site, p_at, 'his phone');
    if coalesce(r,'') = '' and coalesce(p_sched,false) and coalesce((select (data->>'appClock')::boolean from records where coll='emps' and id = v_who),false) then r := private.app_switch(v_who, p_site, p_at); end if;
  end if;
  return coalesce(r, '');
end $function$
CREATE OR REPLACE FUNCTION public.apply_stock_moves(moves jsonb)
 RETURNS TABLE(id text, qty numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare m jsonb;
begin
  for m in select * from jsonb_array_elements(moves) loop
    update public.records t
      set data = jsonb_set(t.data,'{qty}', to_jsonb(greatest(0, coalesce((t.data->>'qty')::numeric,0) + coalesce((m->>'delta')::numeric,0)))),
          updated_by = m->>'by', updated_at = now()
      where t.coll='stock' and t.id = m->>'id' and not t.deleted;
    return query select t.id, (t.data->>'qty')::numeric from public.records t where t.coll='stock' and t.id = m->>'id';
  end loop;
end $function$
CREATE OR REPLACE FUNCTION public.apply_stock_txn(txn jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare txnid text; fp text; existing_fp text; m jsonb; me jsonb; actor text; can_adjust boolean;
        cur numeric; newq numeric; nm text; items jsonb := '[]'::jsonb; out_qtys jsonb; kind text; seqv bigint;
        rsn text; ex boolean; cnt boolean; unc boolean; nowms bigint := (extract(epoch from now())*1000)::bigint;
begin
  txnid := txn->>'id';
  if coalesce(txnid,'') = '' then raise exception 'txn id required' using errcode='22023'; end if;
  me := public.my_emp_data(); actor := me->>'id';
  if coalesce(actor,'') = '' then raise exception 'not allowed' using errcode='42501'; end if;
  can_adjust := (me->>'role' in ('owner','manager','office')) or coalesce((me->>'all')::boolean,false);
  kind := coalesce(txn->>'kind','');
  if kind not in ('in','out','set') then raise exception 'bad kind' using errcode='22023'; end if;
  rsn := nullif(left(trim(coalesce(txn->>'reason','')), 300), '');
  fp := md5(kind || '|' || coalesce((txn->'moves')::text,'[]'));

  insert into public.stock_applied(id, fingerprint) values(txnid, fp) on conflict (id) do nothing;
  if not found then
    select fingerprint into existing_fp from public.stock_applied where id = txnid;
    if existing_fp is distinct from fp then
      raise exception 'txn_reuse_conflict: id % reused with different content', txnid using errcode='23505';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('id', ids.mid, 'qty', coalesce((r.data->>'qty')::numeric,0), 'qv', coalesce((r.data->>'qv')::bigint,0))), '[]'::jsonb) into out_qtys
      from (select distinct m2->>'id' as mid from jsonb_array_elements(coalesce(txn->'moves','[]'::jsonb)) m2) ids
      left join public.records r on r.coll='stock' and r.id = ids.mid and not r.deleted;
    return jsonb_build_object('duplicate', true, 'qtys', out_qtys);
  end if;

  perform set_config('app.stock_txn','1', true);
  for m in select value from jsonb_array_elements(coalesce(txn->'moves','[]'::jsonb)) order by value->>'id' loop
    -- B4 input checks (as in production's security fix)
    if jsonb_typeof(m) <> 'object' or coalesce(m->>'id','') = '' then raise exception 'bad move' using errcode = '22023'; end if;
    if (m ? 'set' and public._num(m->>'set') is null) or (m ? 'expect' and public._num(m->>'expect') is null) then
      raise exception 'count must be a number' using errcode = '22023'; end if;
    if (m ? 'delta') and public._num(m->>'delta') is null then raise exception 'amount must be a number' using errcode = '22023'; end if;
    -- A2 signs: a pick-up only takes out, a return only brings in, a count only sets
    if (kind = 'set') <> (m ? 'set') then raise exception 'bad move for this kind of change' using errcode = '22023'; end if;
    if kind = 'out' and coalesce(public._num(m->>'delta'), 0) >= 0 then raise exception 'a pick-up must take items out' using errcode = '22023'; end if;
    if kind = 'in' and coalesce(public._num(m->>'delta'), 0) <= 0 then raise exception 'a return must bring items in' using errcode = '22023'; end if;
    if (m ? 'delta') and not (m ? 'set') and (m->>'delta')::numeric > 0 then
      insert into public.records(coll,id,data,deleted,updated_by,updated_at)
        values('stock', m->>'id', jsonb_build_object('id',m->>'id','name',coalesce(m->>'name',m->>'id'),'unit',coalesce(m->>'unit','pc'),'min',0,'qty',0,'qv',0), false, actor, now())
        on conflict (coll,id) do update set deleted = false, data = public.records.data || jsonb_build_object('qty', 0), updated_by = actor, updated_at = now()
          where public.records.deleted;   -- B1: an item removed from the list comes back when it is put back
    end if;
    cur := null; nm := null; cnt := false; unc := false;
    select (data->>'qty')::numeric, data->>'name', (jsonb_typeof(data) = 'object' and data ? 'counted') into cur, nm, cnt
      from public.records where coll='stock' and id = m->>'id' and not deleted for update;
    ex := found;
    if m ? 'set' then
      if not can_adjust then raise exception 'manual stock adjustment is office/owner only' using errcode='42501'; end if;
      if (m ? 'expect') and coalesce(cur,0) <> (m->>'expect')::numeric then
        raise exception 'stock_changed_recount: % now %, you saw %', m->>'id', coalesce(cur,0), m->>'expect' using errcode='40001';
      end if;
      newq := greatest(0, (m->>'set')::numeric);
    else
      if (m->>'delta') is null then raise exception 'move needs delta or set' using errcode='22023'; end if;
      newq := coalesce(cur,0) + (m->>'delta')::numeric;
      if newq < 0 and kind = 'out' and ex and not cnt then
        -- S1: this item's opening count is not verified yet — the pick-up is recorded, the garage count stays at 0
        unc := true; newq := 0;
      elsif newq < 0 then
        raise exception 'insufficient_stock: % available %, requested %', coalesce(nm,m->>'name',m->>'id'), coalesce(cur,0), abs((m->>'delta')::numeric) using errcode='P0001';
      end if;
    end if;
    if cur is null then
      insert into public.records(coll,id,data,deleted,updated_by,updated_at)
        values('stock', m->>'id', jsonb_build_object('id',m->>'id','name',coalesce(m->>'name',m->>'id'),'unit',coalesce(m->>'unit','pc'),'min',0,'qty',newq,'qv',1)
               || case when m ? 'set' then jsonb_build_object('counted', nowms, 'countedBy', actor) else '{}'::jsonb end, false, actor, now())
        on conflict (coll,id) do update set deleted = false, data = public.records.data || jsonb_build_object('qty', newq, 'qv', coalesce((public.records.data->>'qv')::bigint,0)+1)
               || case when m ? 'set' then jsonb_build_object('counted', nowms, 'countedBy', actor) else '{}'::jsonb end, updated_by=actor, updated_at=now();
    else
      update public.records set data = data || jsonb_build_object('qty', newq, 'qv', coalesce((data->>'qv')::bigint,0)+1)
               || case when m ? 'set' then jsonb_build_object('counted', nowms, 'countedBy', actor) else '{}'::jsonb end, updated_by=actor, updated_at=now()
        where coll='stock' and id = m->>'id';
    end if;
    items := items || (jsonb_build_object('id', m->>'id', 'name', coalesce(nm,m->>'name',m->>'id'),
               'before', coalesce(cur,0), 'after', newq,
               'change', case when m ? 'set' then newq - coalesce(cur,0) else (m->>'delta')::numeric end)
             || case when unc then jsonb_build_object('uncounted', true) else '{}'::jsonb end);
  end loop;

  seqv := nextval('public.stock_seq');
  insert into public.records(coll,id,data,deleted,updated_by,updated_at)
    values('stockLog', txnid, jsonb_build_object(
      'kind', kind, 'by', actor, 'approvedBy', case when kind='set' then actor else null end,
      'site', txn->>'site', 'dir', case when kind='in' then 'from' else 'to' end,
      'items', items, 'ts', coalesce((txn->>'ts')::bigint, (extract(epoch from now())*1000)::bigint),
      'serverTs', (extract(epoch from now())*1000)::bigint, 'seq', seqv, 'applied', true, 'auth', true,
      'reason', rsn, 'src', nullif(left(trim(coalesce(txn->>'src','')), 200), ''))
      - case when rsn is null then array['reason'] else array[]::text[] end
      - case when nullif(trim(coalesce(txn->>'src','')), '') is null then array['src'] else array[]::text[] end,
      false, actor, now())
    on conflict (coll,id) do nothing;
  perform set_config('app.stock_txn','', true);

  select coalesce(jsonb_agg(jsonb_build_object('id', ids.mid, 'qty', coalesce((r.data->>'qty')::numeric,0), 'qv', coalesce((r.data->>'qv')::bigint,0))), '[]'::jsonb) into out_qtys
    from (select distinct m2->>'id' as mid from jsonb_array_elements(coalesce(txn->'moves','[]'::jsonb)) m2) ids
    left join public.records r on r.coll='stock' and r.id = ids.mid and not r.deleted;
  return jsonb_build_object('duplicate', false, 'qtys', out_qtys);
end $function$
CREATE OR REPLACE FUNCTION public.backup_files_since(p_since timestamp with time zone)
 RETURNS TABLE(name text, type text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.name, o.metadata->>'mimetype', o.created_at from storage.objects o
   where o.bucket_id = 'files' and o.created_at > coalesce(p_since, 'epoch') order by o.created_at, o.name;
$function$
CREATE OR REPLACE FUNCTION public.backup_health_check()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare last timestamptz; enabled boolean; o record; msg text;
begin
  enabled := exists (select 1 from public.server_config where k = 'backup_repo' and coalesce(v,'') <> '');
  if not enabled then return 'off-site backup not set up'; end if;
  select (v::jsonb->>'at')::timestamptz into last from public.server_config where k = 'last_backup_records';
  if last is not null and last > now() - interval '30 hours' then return 'ok: last backup ' || last; end if;
  msg := '⚠ Nightly backup is overdue' || case when last is null then ' (none yet)' else ' — last good copy ' || to_char(last at time zone 'America/New_York', 'Mon DD HH12:MI AM') end
         || '. Check the electrix-backups page on GitHub, or ask Claude.';
  for o in select id from public.records where coll = 'emps' and not deleted and data->>'role' = 'owner' loop
    insert into public.records(coll, id, data, deleted) values ('inbox', 'bk' || to_char(now(), 'YYYYMMDD') || o.id,
      jsonb_build_object('id', 'bk' || to_char(now(), 'YYYYMMDD') || o.id, 'to', o.id, 'ts', (extract(epoch from now()) * 1000)::bigint,
                         'msg', msg, 'from', o.id, 'kind', 'warn', 'link', null, 'read', false), false)
    on conflict (coll, id) do nothing;
  end loop;
  return 'alerted: ' || msg;
end $function$
CREATE OR REPLACE FUNCTION public.backup_note(p_k text, p_v text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_k not in ('last_backup_records','last_backup_files') then raise exception 'not a backup note'; end if;
  update public.server_config set v = p_v where k = p_k;
  if not found then insert into public.server_config(k, v) values (p_k, p_v); end if;
end $function$
CREATE OR REPLACE FUNCTION public.backup_records()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; s int := (current_date - date '2026-01-01') % 14; keep_days constant int := 7;
begin
  delete from public.records_backup where slot = s or day <= current_date - keep_days;
  insert into public.records_backup (slot, day, coll, id, data, deleted, updated_by, updated_at)
    select s, current_date, coll, id, data, deleted, updated_by, updated_at from public.records;
  get diagnostics n = row_count;
  return n;
end $function$
CREATE OR REPLACE FUNCTION public.backup_restore(p jsonb, p_mode text DEFAULT 'check'::text, p_target text DEFAULT 'public'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; cur record; missing int := 0; differ int := 0; same int := 0; written int := 0; newdata jsonb; tgt text;
begin
  if coalesce(p->'meta'->>'format','') <> 'electrix-backup-1' then raise exception 'not an Electrix backup'; end if;
  if p_mode not in ('check','missing','all') then raise exception 'mode must be check, missing or all'; end if;
  if p_target not in ('public','drill') then raise exception 'target must be public or drill'; end if;
  tgt := case when p_target = 'drill' then 'drill.records' else 'public.records' end;
  -- the encrypted file already proves it is complete and unchanged (AES-GCM + SHA-256); here we make sure nothing was cut off
  if jsonb_typeof(p->'records') <> 'array' or jsonb_array_length(p->'records') <> coalesce((p->'meta'->>'records')::int, -1) then
    raise exception 'backup file is incomplete (record count does not match)'; end if;
  for r in select value from jsonb_array_elements(p->'records') loop
    execute format('select data, deleted from %s where coll = $1 and id = $2', tgt) into cur using r->>'coll', r->>'id';
    if cur is null then missing := missing + 1;
    elsif cur.data is distinct from (r->'data') or cur.deleted is distinct from (r->>'deleted')::boolean then differ := differ + 1;
    else same := same + 1; continue; end if;
    if p_mode = 'check' then continue; end if;
    if p_mode = 'missing' and cur is not null and not (cur.deleted and not (r->>'deleted')::boolean) then continue; end if;
    newdata := r->'data';
    if r->>'coll' = 'sched' and cur is not null and jsonb_typeof(newdata) = 'object' then
      newdata := newdata || jsonb_build_object('rev', greatest(coalesce(public._num(newdata->>'rev'),0), coalesce(public._num(cur.data->>'rev'),0) + 1));
    end if;
    execute format('insert into %s(coll,id,data,deleted,updated_by,updated_at) values ($1,$2,$3,$4,$5,now())
                    on conflict (coll,id) do update set data = excluded.data, deleted = excluded.deleted, updated_by = excluded.updated_by, updated_at = now()', tgt)
      using r->>'coll', r->>'id', newdata, (r->>'deleted')::boolean, 'restore:' || coalesce(p->'meta'->>'taken_at','?');
    written := written + 1;
  end loop;
  return jsonb_build_object('mode',p_mode,'target',p_target,'in_backup',jsonb_array_length(p->'records'),'same',same,'differ',differ,'missing',missing,'written',written);
end $function$
CREATE OR REPLACE FUNCTION public.backup_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare recs jsonb; sa jsonb; files jsonb; fns jsonb; trg jsonb; pol jsonb; tbl jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('coll',coll,'id',id,'data',data,'deleted',deleted,'updated_by',updated_by,'updated_at',updated_at) order by coll,id),'[]'::jsonb) into recs from public.records;
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'at',at,'fingerprint',fingerprint) order by id),'[]'::jsonb) into sa from public.stock_applied;
  select coalesce(jsonb_agg(jsonb_build_object('name',name,'size',(metadata->>'size')::bigint,'type',metadata->>'mimetype','updated_at',updated_at) order by name),'[]'::jsonb) into files from storage.objects where bucket_id = 'files';
  select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'def',pg_get_functiondef(p.oid)) order by n.nspname,p.proname),'[]'::jsonb) into fns
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public','private') and p.prokind = 'f';
  select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'def',pg_get_triggerdef(t.oid)) order by c.relname,t.tgname),'[]'::jsonb) into trg
    from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and not t.tgisinternal;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.schemaname,x.tablename,x.policyname),'[]'::jsonb) into pol from pg_policies x where x.schemaname in ('public','storage');
  select coalesce(jsonb_agg(jsonb_build_object('table',table_name,'columns',cols) order by table_name),'[]'::jsonb) into tbl from (
    select table_name, jsonb_agg(jsonb_build_object('name',column_name,'type',data_type,'default',column_default,'null',is_nullable) order by ordinal_position) cols
    from information_schema.columns where table_schema = 'public' group by table_name) q;
  return jsonb_build_object('meta', jsonb_build_object('format','electrix-backup-1','taken_at',now(),'database',current_database(),
            'records',jsonb_array_length(recs),'records_md5',md5(recs::text),'stock_applied',jsonb_array_length(sa),'files',jsonb_array_length(files)),
         'records',recs,'stock_applied',sa,'files',files,
         'schema',jsonb_build_object('functions',fns,'triggers',trg,'policies',pol,'tables',tbl));
end $function$
CREATE OR REPLACE FUNCTION public.bg_key_drop(p_dev text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update private.bg_keys set key_hash = 'revoked', last_used = now() where dev = p_dev and uid = auth.uid() $function$
CREATE OR REPLACE FUNCTION public.bg_key_register(p_dev text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u uuid := auth.uid(); e jsonb; k text;
begin
  if u is null or p_dev is null or length(p_dev) < 8 or length(p_dev) > 80 then return null; end if;
  e := public.my_emp_data();
  if e = '{}'::jsonb or coalesce(e->>'id','') = '' then return null; end if;
  k := encode(extensions.gen_random_bytes(24), 'hex');
  insert into private.bg_keys(dev, who, uid, key_hash, created_at, last_used)
    values (p_dev, e->>'id', u, encode(extensions.digest(k, 'sha256'), 'hex'), now(), null)
    on conflict (dev) do update set who = excluded.who, uid = excluded.uid, key_hash = excluded.key_hash, created_at = now(), last_used = null;
  return k;
end $function$
CREATE OR REPLACE FUNCTION public.can_see(c text, d jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select c <> 'keep' or d->>'owner' = public.my_emp() or coalesce(d->'collab', '[]'::jsonb) ? public.my_emp();
$function$
CREATE OR REPLACE FUNCTION public.can_see2(c text, d jsonb, me jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case
    when c not in ('keep','inbox','push','meets','punches','timeoff','goHomeLog','travel','exps','emphr','stockLog','rejq',
                   'incidents','msgs','apps','invites','fixes','ptask','jobs','bcol','orr','rates','fcpay','qbexp') then true
    when c = 'keep' then d->>'owner' = me->>'id' or coalesce(d->'collab','[]'::jsonb) ? (me->>'id')
                         or (jsonb_typeof(d->'assign') = 'array' and d->'assign' ? (me->>'id'))
    when c = 'jobs' then me->>'role' = 'owner' or (coalesce((me->>'viewAs')::boolean,false) and me->>'role'='office') or d->>'from' = me->>'id' or (case jsonb_typeof(d->'to') when 'array' then d->'to' when 'string' then jsonb_build_array(d->'to') else '[]'::jsonb end) ?| array[me->>'id', coalesce(nullif(me->>'crew',''), '~')]
    when c = 'bcol' then d->>'owner' = me->>'id' or me->>'role' = 'owner' or (coalesce((me->>'viewAs')::boolean,false) and me->>'role'='office')
    when c = 'ptask' then d->>'owner' = me->>'id' or me->>'role' = 'owner' or (coalesce((me->>'viewAs')::boolean,false) and me->>'role'='office')
    when c = 'inbox' then d->>'to' = me->>'id'
    when c = 'push' then d->>'who' = me->>'id'
    when c = 'meets' then me->>'role' = 'owner' or (coalesce((me->>'viewAs')::boolean,false) and me->>'role'='office') or d->>'by' = me->>'id' or coalesce(d->'with','[]'::jsonb) ? (me->>'id')
    when c = 'emphr' then d->>'who' = me->>'id' or me->>'role' in ('owner','manager','office') or (me->>'all')::boolean
    when c in ('rates','fcpay','qbexp') then me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll')
    when c = 'travel' then me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll') or d->>'who' = me->>'id'
    when c in ('punches','timeoff','goHomeLog') then
         me->>'role' in ('owner','manager','office') or (me->>'all')::boolean or d->>'who' = me->>'id'
    when c in ('fixes','incidents') then
         me->>'role' in ('owner','manager','office') or coalesce((me->>'all')::boolean,false) or d->>'who' = me->>'id' or d->>'by' = me->>'id'
    when c in ('stockLog','rejq') then
         me->>'role' in ('owner','manager','office') or coalesce((me->>'all')::boolean,false) or d->>'by' = me->>'id'
    when c = 'exps' then
         me->>'role' in ('owner','manager') or (me->>'all')::boolean
      or (me->>'role' = 'office' and me->>'title' in ('Payroll','Bookkeeper')) or d->>'who' = me->>'id'
    when c = 'msgs' then me->>'role' = 'owner' or d->>'from' = me->>'id' or d->>'to' = me->>'id' or coalesce(d->>'k','') like 'g:%'
    when c in ('apps','invites') then me->>'role' in ('owner','manager','office') or coalesce((me->>'all')::boolean,false)
    when c = 'orr' then me->>'role' in ('owner','manager') or coalesce((me->>'all')::boolean,false) or (me->>'role' = 'office' and coalesce(me->>'title','') <> 'Accountant')
    else true end;
$function$
