CREATE OR REPLACE FUNCTION public.catalog_merge(p_from text, p_into text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); a jsonb; b jsonb; qa numeric; qb numeric; nowms bigint := (extract(epoch from now())*1000)::bigint; lid text;
        codes jsonb;
begin
  if not private.catalog_mgr(me) then raise exception 'only the people who manage the material list can merge materials' using errcode = '42501'; end if;
  if coalesce(p_from,'') = '' or coalesce(p_into,'') = '' or p_from = p_into then raise exception 'pick two different materials' using errcode = '22023'; end if;
  -- lock both in a fixed order
  perform 1 from public.records where coll = 'stock' and id in (p_from, p_into) order by id for update;
  select data into a from public.records where coll = 'stock' and id = p_from and not deleted;
  select data into b from public.records where coll = 'stock' and id = p_into and not deleted;
  if a is null or b is null then raise exception 'that material is not in the list' using errcode = '22023'; end if;
  if coalesce(a->>'mergedInto','') <> '' then return jsonb_build_object('ok', true, 'already', true); end if;
  if coalesce(b->>'mergedInto','') <> '' then raise exception 'merge into the material that stays' using errcode = '22023'; end if;
  qa := coalesce(public._num(a->>'qty'), 0); qb := coalesce(public._num(b->>'qty'), 0);
  codes := case when jsonb_typeof(a->'codes') = 'array' or jsonb_typeof(b->'codes') = 'array' then
             (select coalesce(jsonb_agg(distinct c), '[]'::jsonb) from (
                select jsonb_array_elements(case when jsonb_typeof(b->'codes') = 'array' then b->'codes' else '[]'::jsonb end) c
                union all select jsonb_array_elements(case when jsonb_typeof(a->'codes') = 'array' then a->'codes' else '[]'::jsonb end)) q) end;
  perform set_config('app.stock_txn', '1', true);
  update public.records set data = data || jsonb_build_object('qty', qb + qa, 'qv', coalesce(public._num(data->>'qv')::bigint, 0) + 1,
           'aka', (select coalesce(jsonb_agg(distinct x), '[]'::jsonb) from (
                     select jsonb_array_elements_text(case when jsonb_typeof(b->'aka') = 'array' then b->'aka' else '[]'::jsonb end) x
                     union select jsonb_array_elements_text(case when jsonb_typeof(a->'aka') = 'array' then a->'aka' else '[]'::jsonb end)
                     union select a->>'name') q where coalesce(x,'') <> ''),
           'crev', coalesce(public._num(b->>'crev')::int, 0) + 1, 'cedBy', me->>'id', 'cedAt', nowms)
           || case when codes is not null then jsonb_build_object('codes', codes) else '{}'::jsonb end
           || case when coalesce((b->>'fav')::boolean, false) or coalesce((a->>'fav')::boolean, false) then jsonb_build_object('fav', true) else '{}'::jsonb end,
         updated_by = me->>'id', updated_at = now()
   where coll = 'stock' and id = p_into;
  update public.records set data = data || jsonb_build_object('qty', 0, 'qv', coalesce(public._num(data->>'qv')::bigint, 0) + 1, 'hidden', true,
           'mergedInto', p_into, 'crev', coalesce(public._num(a->>'crev')::int, 0) + 1, 'cedBy', me->>'id', 'cedAt', nowms),
         updated_by = me->>'id', updated_at = now()
   where coll = 'stock' and id = p_from;
  if qa <> 0 then
    lid := 'merge_' || p_from || '_' || nowms;
    insert into public.records(coll, id, data, deleted, updated_by, updated_at)
    values ('stockLog', lid, jsonb_build_object('kind', 'set', 'by', me->>'id', 'approvedBy', me->>'id', 'ts', nowms, 'serverTs', nowms,
            'seq', nextval('public.stock_seq'), 'applied', true, 'auth', true, 'reason', 'Merged duplicate: ' || coalesce(a->>'name', p_from) || ' → ' || coalesce(b->>'name', p_into),
            'items', jsonb_build_array(
               jsonb_build_object('id', p_from, 'name', a->>'name', 'before', qa, 'after', 0, 'change', -qa),
               jsonb_build_object('id', p_into, 'name', b->>'name', 'before', qb, 'after', qb + qa, 'change', qa))), false, me->>'id', now())
    on conflict (coll, id) do nothing;
  end if;
  perform set_config('app.stock_txn', '', true);
  return jsonb_build_object('ok', true, 'moved', qa, 'qty', qb + qa);
end $function$
CREATE OR REPLACE FUNCTION public.codebook_search(q text, lim integer DEFAULT 150)
 RETURNS TABLE(vol smallint, idx integer, label text, head text, title text, snip text, score real)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
-- Plain-language search of the code book. Filler words are dropped ("what's the code for kitchens" -> kitchen),
-- each word also matches a few trade words (pool = swimming, bonding = equipotential, gfi = gfci).
-- Pages with every word come first, then pages with some of the words; a section whose name has the word gets a push.
declare tq tsquery; tq_or tsquery; tqs tsquery[] := '{}'; secs text[]; qq text := lower(btrim(coalesce(q,''))); parts text[]; w text; alts text;
begin
  if not is_member() then raise exception 'not allowed'; end if;
  if length(qq) < 2 then return; end if;
  secs := array(select m[1] from regexp_matches(qq, '(\d{2,3}\.\d+)', 'g') m);
  qq := regexp_replace(qq, '(\d{2,3}\.\d+)(\([a-z0-9]+\))*', ' ', 'g');
  qq := regexp_replace(qq, '[''’]s\M', '', 'g');
  parts := array(
    select x from regexp_split_to_table(qq, '[^a-z0-9]+') x
    where x <> '' and x not in ('what','whats','which','where','when','how','is','are','the','a','an','code','codes','nec','for','by','of','on','in','at','to','with','around','near','about','me','tell','show','find','give','get','need','do','does','i','we','my','our','requirement','requirements','required','rule','rules','section','sections','article','articles','and','or','can','should','must','be','it','this','that','there','all','any','everything','info','information','book','say','says','page','pages'));
  for w in select unnest(parts) loop
    alts := (select string_agg(distinct quote_literal(l)||':*', ' | ') from (
       select unnest(tsvector_to_array(to_tsvector('english', w))) l
       union select s from (values ('pool','swim'),('swim','pool'),('pools','swim'),('bond','equipotenti'),('bonding','equipotenti'),('spa','tub'),('tub','spa'),('jacuzzi','tub'),('jacuzzi','spa'),('gfi','gfci'),('gfis','gfci'),('romex','nm'),('panel','panelboard'),('panel','switchboard'),('ev','vehicl'),('solar','pv'),('solar','photovolta'),('grounding','ground')) syn(k,s) where syn.k = w
    ) z where l is not null and length(l) > 0);
    if alts is not null then
      tqs := tqs || to_tsquery('english', '('||alts||')');
      tq := case when tq is null then to_tsquery('english', '('||alts||')') else tq && to_tsquery('english','('||alts||')') end;
      tq_or := case when tq_or is null then to_tsquery('english', '('||alts||')') else tq_or || to_tsquery('english','('||alts||')') end;
    end if;
  end loop;
  return query
  with hits as (
    select p.vol, p.idx, p.label, p.head, p.body, p.tsv,
      (select t.title from codebook_toc t where t.vol = p.vol and p.head <> '' and t.title like p.head||' %' order by t.ord limit 1) as ttl
    from codebook_pages p
    where (tq_or is not null and p.tsv @@ tq_or) or p.head = any(secs)
  ), scored as (
    select h.*,
      (( (select count(*) from unnest(tqs) x where h.tsv @@ x)
        + (select count(*) from unnest(tqs) x where h.ttl is not null and to_tsvector('english', h.ttl) @@ x) * 0.6
        + case when tq_or is not null then ts_rank_cd(h.tsv, tq_or, 1) else 0 end
        + case when h.head = any(secs) then 5 else 0 end
        + case when exists(select 1 from unnest(secs) s where h.body ilike '%'||s||'%') then 0.5 else 0 end)
       * case when h.label ~ '^[ivxlc]+$' or left(h.body,60) ~* '(review questions|final exam|\| *index)' then 0.08 when coalesce(h.head,'') = '' then 0.45 else 1 end
      )::real as sc
    from hits h
  ), top as (select * from scored order by sc desc, vol, idx limit greatest(1, least(lim, 200)))
  select t.vol, t.idx, t.label, t.head, t.ttl,
    case when tq_or is not null then ts_headline('english', t.body, tq_or, 'MaxWords=26, MinWords=10, StartSel=<<, StopSel=>>, MaxFragments=1, FragmentDelimiter=" … "')
      else left(t.body, 160) end,
    t.sc
  from top t order by t.sc desc, t.vol, t.idx;
end $function$
CREATE OR REPLACE FUNCTION public.device_ping(p_dev text, p_ver text, p_pending integer, p_rejects integer, p_err text, p_ua text, p_online boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare w text := (public.my_emp_data())->>'id';
begin
  if w is null or coalesce(p_dev,'') = '' then return; end if;
  insert into private.devices(dev, who, ver, pending, rejects, err, ua, online, stuck_since)
  values (left(p_dev,40), w, left(p_ver,40), p_pending, p_rejects, left(p_err,200), left(p_ua,160), p_online, case when p_pending > 0 then now() end)
  on conflict (dev) do update set who = excluded.who, ver = excluded.ver, pending = excluded.pending, rejects = excluded.rejects, err = excluded.err,
    ua = excluded.ua, online = excluded.online, last_at = now(),
    stuck_since = case when excluded.pending > 0 then coalesce(private.devices.stuck_since, now()) else null end;
end $function$
