CREATE OR REPLACE FUNCTION public.error_digest()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tot int; ppl int; stuck int; refused int; crash int; top text; o record; nid text; msg text; n int := 0;
        nowms bigint := (extract(epoch from now()) * 1000)::bigint; day text := to_char(now() at time zone 'America/New_York', 'YYYYMMDD');
begin
  select coalesce(sum(e.n),0), count(distinct e.who),
         coalesce(sum(e.n) filter (where e.kind = 'stuck'),0), coalesce(sum(e.n) filter (where e.kind in ('refused','stock')),0),
         coalesce(sum(e.n) filter (where e.kind = 'error'),0)
    into tot, ppl, stuck, refused, crash
    from private.client_errors e where e.at > now() - interval '24 hours';
  if tot = 0 then return 0; end if;
  select string_agg(x, ' · ') into top from (
    select left(e.msg, 60) || ' (' || sum(e.n) || '×)' x from private.client_errors e
     where e.at > now() - interval '24 hours' group by left(e.msg, 60) order by sum(e.n) desc limit 3) q;
  for o in select id, data->>'lang' lang from public.records where coll = 'emps' and not deleted and data->>'role' = 'owner'
             and not coalesce((data->>'inactive')::boolean, false) loop
    nid := 'nerr' || day || o.id;
    if exists (select 1 from public.records where coll = 'inbox' and id = nid) then continue; end if;
    msg := case when o.lang = 'es'
      then '⚠ Problemas en la app (últimas 24 h): ' || tot || ' en ' || ppl || ' teléfono(s)'
           || case when stuck > 0 then ' · ' || stuck || ' con cambios sin enviar por horas' else '' end
           || case when refused > 0 then ' · ' || refused || ' cambios rechazados' else '' end || '. ' || coalesce(top, '')
      else '⚠ App problems in the last 24 h: ' || tot || ' on ' || ppl || ' phone(s)'
           || case when stuck > 0 then ' · ' || stuck || ' with changes unsent for hours' else '' end
           || case when refused > 0 then ' · ' || refused || ' refused changes' else '' end || '. ' || coalesce(top, '') end;
    insert into public.records (coll, id, data, deleted, updated_by, updated_at)
    values ('inbox', nid, jsonb_build_object('id', nid, 'to', o.id, 'msg', left(msg, 400), 'kind', 'warn', 'ts', nowms, 'read', false,
            'link', null, 'auto', true), false, 'server', now());
    n := n + 1;
  end loop;
  return n;
end $function$
CREATE OR REPLACE FUNCTION public.fc_key_status()
 RETURNS TABLE(k text, last4 text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data();
begin
  if not (me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll')) then raise exception 'not allowed' using errcode = '42501'; end if;
  return query select f.k, right(f.v, 4), f.updated_at from private.fc_keys f;
end $function$
CREATE OR REPLACE FUNCTION public.fc_keys_server()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from private.fc_keys;
$function$
CREATE OR REPLACE FUNCTION public.fc_set_key(p_k text, p_v text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); v text := btrim(coalesce(p_v, ''));
begin
  if not (me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll')) then
    raise exception 'only the owner or Payroll can set the Fingercheck keys' using errcode = '42501'; end if;
  if p_k not in ('api','usa','inc') then raise exception 'unknown key' using errcode = '22023'; end if;
  if v = '' then delete from private.fc_keys where k = p_k; return null; end if;
  if length(v) > 500 or v ~ '\s' then raise exception 'that does not look like a key' using errcode = '22023'; end if;
  insert into private.fc_keys (k, v, updated_at, updated_by) values (p_k, v, now(), me->>'id')
  on conflict (k) do update set v = excluded.v, updated_at = now(), updated_by = excluded.updated_by;
  return right(v, 4);
end $function$
CREATE OR REPLACE FUNCTION public.file_ok(path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when path like 'media/%' then
      exists (select 1 from public.records r where not r.deleted and strpos(r.data::text, '/files/media/') > 0
              and strpos(r.data::text, '/files/' || path) > 0
              and coalesce(public.can_see2(r.coll, r.data, public.my_emp_data()), false))
    when path like 'trello/%' and split_part(path,'/',2) <> '' then
      exists (select 1 from public.records r where r.coll = 'sites' and r.id = split_part(path,'/',2) and not r.deleted
              and coalesce(public.can_see2(r.coll, r.data, public.my_emp_data()), false))
    when split_part(path,'/',2) <> '' then
      exists (select 1 from public.records r where r.coll = split_part(path,'/',1) and r.id = split_part(path,'/',2) and not r.deleted
              and coalesce(public.can_see2(r.coll, r.data, public.my_emp_data()), false))
    else false end;
$function$
CREATE OR REPLACE FUNCTION public.guard_bcol()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb;
begin
  if current_user not in ('authenticated','anon') or auth.uid() is null then return new; end if;
  me := public.my_emp_data();
  if new.deleted then raise exception 'board columns are not deleted' using errcode = '42501'; end if;
  if jsonb_typeof(new.data) <> 'object' or new.id <> 'bcol_' || (me->>'id') or new.data->>'owner' is distinct from me->>'id' then
    raise exception 'only you can change your own board' using errcode = '42501'; end if;
  if jsonb_typeof(new.data->'cols') <> 'array' or jsonb_array_length(new.data->'cols') > 30 then
    raise exception 'bad board columns' using errcode = '22023'; end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_catalog()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb; mgr boolean; o jsonb; n jsonb := new.data; f text; changed boolean := false; nm text; nowms bigint := (extract(epoch from now())*1000)::bigint;
        keep jsonb := '{}'::jsonb;
begin
  if current_user not in ('authenticated','anon') or auth.uid() is null then return new; end if;
  if coalesce(current_setting('app.stock_txn', true), '') = '1' then return new; end if;   -- receiving stock (apply_stock_txn) may add an item
  me := public.my_emp_data();
  mgr := private.catalog_mgr(me);
  if new.deleted and new.coll = 'stock' then                                 -- removing a material: catalog managers only (soft, kept in history)
    if not mgr and tg_op = 'UPDATE' and not old.deleted then
      raise exception 'only the people who manage the material list can remove materials — hide it instead' using errcode = '42501'; end if;
    return new; end if;
  if jsonb_typeof(n) <> 'object' then raise exception 'not allowed' using errcode = '42501'; end if;
  o := case when tg_op = 'UPDATE' and not old.deleted and jsonb_typeof(old.data) = 'object' then old.data end;
  if new.coll = 'mtpl' then
    if not mgr then raise exception 'only the people who manage the material list can change templates' using errcode = '42501'; end if;
    if new.deleted then raise exception 'a template is hidden, not deleted' using errcode = '42501'; end if;
    new.data := n || jsonb_build_object('id', new.id, 'eby', me->>'id', 'eat', nowms);
    return new;
  end if;
  if new.deleted then return new; end if;
  if o is null then                                                        -- a new material
    if not mgr then raise exception 'only the people who manage the material list can add materials' using errcode = '42501'; end if;
    nm := lower(btrim(coalesce(n->>'name','')));
    if nm = '' then raise exception 'a material needs a name' using errcode = '42501'; end if;
    if exists (select 1 from public.records s where s.coll = 'stock' and not s.deleted and s.id <> new.id and jsonb_typeof(s.data) = 'object'
                and (lower(btrim(s.data->>'name')) = nm or (jsonb_typeof(s.data->'aka') = 'array' and exists (select 1 from jsonb_array_elements_text(s.data->'aka') a where lower(btrim(a)) = nm)))) then
      raise exception 'already in the material list: %', n->>'name' using errcode = '42501'; end if;
    new.data := n || jsonb_build_object('crev', 1, 'cedBy', me->>'id', 'cedAt', nowms);
    return new;
  end if;
  foreach f in array private.catalog_fields() loop
    if f in ('crev','cedBy','cedAt') then continue; end if;
    if n->f is distinct from o->f then changed := true; end if;
  end loop;
  if not changed then
    -- nothing about the material itself changed: keep the server's catalog fields exactly
    foreach f in array array['crev','cedBy','cedAt'] loop
      n := n - f; if o ? f then n := n || jsonb_build_object(f, o->f); end if;
    end loop;
    new.data := n; return new;
  end if;
  if not mgr or (n->'crev') is distinct from (o->'crev') then
    -- not a catalog manager, or a phone that had an older copy of this material: the catalog fields stay as they are on
    -- the server; anything else in the change (barcodes, photo, model …) still goes through
    foreach f in array private.catalog_fields() loop
      n := n - f; if o ? f then n := n || jsonb_build_object(f, o->f); end if;
    end loop;
    new.data := n; return new;
  end if;
  -- a catalog manager's change from the current version
  nm := lower(btrim(coalesce(n->>'name','')));
  if nm = '' then raise exception 'a material needs a name' using errcode = '42501'; end if;
  if lower(btrim(coalesce(o->>'name',''))) <> nm then
    if exists (select 1 from public.records s where s.coll = 'stock' and not s.deleted and s.id <> new.id and jsonb_typeof(s.data) = 'object'
                and lower(btrim(s.data->>'name')) = nm and not coalesce((s.data->>'hidden')::boolean, false)) then
      raise exception 'another material already has that name: %', n->>'name' using errcode = '42501'; end if;
    -- remember the old name so an old copy of the app can't add it again as a new material
    n := n || jsonb_build_object('aka', (select coalesce(jsonb_agg(distinct x), '[]'::jsonb) from (
           select jsonb_array_elements_text(case when jsonb_typeof(o->'aka') = 'array' then o->'aka' else '[]'::jsonb end) x
           union select o->>'name') q where coalesce(x,'') <> '' and lower(btrim(x)) <> nm));
  end if;
  if (n->>'mergedInto') is distinct from (o->>'mergedInto') and coalesce(n->>'mergedInto','') <> '' then
    raise exception 'use "merge duplicates" to merge materials' using errcode = '42501'; end if;
  new.data := n || jsonb_build_object('crev', coalesce(public._num(o->>'crev')::int, 0) + 1, 'cedBy', me->>'id', 'cedAt', nowms);
  return new;
end $function$
