CREATE OR REPLACE FUNCTION public.guard_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb; staff boolean; n jsonb := new.data; o jsonb := old.data; k text;
begin
  if current_user not in ('authenticated','anon') or auth.uid() is null then return new; end if;
  me := public.my_emp_data();
  if me = '{}'::jsonb then raise exception 'not allowed' using errcode = '42501'; end if;
  staff := me->>'role' in ('owner','manager','office') or coalesce((me->>'all')::boolean,false);
  if staff then return new; end if;
  if jsonb_typeof(n) <> 'object' or jsonb_typeof(o) <> 'object' then
    raise exception 'that record must stay an object' using errcode = '42501'; end if;
  if new.coll = 'jobs' then
    if o->>'from' = me->>'id' then return new; end if;
    foreach k in array array['desc','descTr','descLang','site','due','pri','est','media'] loop
      if n->k is distinct from o->k then raise exception 'only the office can change %', k using errcode = '42501'; end if;
    end loop;
    if n->'to' is distinct from o->'to' and not coalesce((me->>'lead')::boolean,false) then
      raise exception 'only the office or a crew leader can reassign a job' using errcode = '42501'; end if;
  elsif new.coll = 'sites' then
    foreach k in array array['name','client','clientX','phone','price','priced','total','customer','custPhone','manager','crew','trello','trelloList'] loop
      if n->k is distinct from o->k then raise exception 'only the office can change %', k using errcode = '42501'; end if;
    end loop;
  elsif new.coll = 'stock' then
    -- catalog fields (name, unit, cat …) are handled by guard_catalog (kept as they are, not refused)
    foreach k in array array['min','brand','price','cost','upc','sku'] loop
      if n->k is distinct from o->k then raise exception 'only the office can change %', k using errcode = '42501'; end if;
    end loop;
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_lists()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb; actor text; o jsonb; n jsonb; k text; ov jsonb; nv jsonb; orev int; base int; nowms bigint := (extract(epoch from now())*1000)::bigint;
        editor boolean; srv boolean; ck text; a jsonb; touched boolean := false; fld text; mats boolean := new.coll = 'mats'; prep boolean; pick boolean;
        st text; d0 jsonb;
begin
  if jsonb_typeof(new.data) <> 'object' or new.deleted then return new; end if;
  o := case when tg_op = 'UPDATE' and not old.deleted and jsonb_typeof(old.data) = 'object' then old.data else '{}'::jsonb end;
  n := new.data;
  srv := not (current_user in ('authenticated','anon') and auth.uid() is not null);
  me := case when srv then '{}'::jsonb else public.my_emp_data() end;
  actor := coalesce(me->>'id', 'server');
  pick := srv or coalesce(current_setting('app.mat_pickup', true), '') = '1';
  -- nothing list-related in old or new → leave the record alone (punch lists); material requests always get their status
  if not mats and not exists (select 1 from jsonb_object_keys(n) x where x like 'li\_%' or x like 'lc\_%')
     and not exists (select 1 from jsonb_object_keys(o) x where x like 'li\_%' or x like 'lc\_%') then return new; end if;
  d0 := case when o = '{}'::jsonb then n else o end;
  editor := srv or pick or private.list_editor(new.coll, d0, me);
  prep := mats and (srv or private.mat_preparer(d0, me));
  -- a) an item or comment is never deleted (removing is done by marking it gone)
  for k in select x from jsonb_object_keys(o) x where (x like 'li\_%' or x like 'lc\_%' or (mats and x like 'pu\_%')) and not (n ? x) loop
    n := n || jsonb_build_object(k, o->k);
  end loop;
  -- pickups (pu_<txn>) are written only by mat_pickup()
  if mats and not pick then
    for k in select x from jsonb_object_keys(n) x where x like 'pu\_%' loop
      if n->k is distinct from o->k then if o ? k then n := n || jsonb_build_object(k, o->k); else n := n - k; end if; end if;
    end loop;
  end if;
  -- b) each changed item
  for k in select x from jsonb_object_keys(n) x where x like 'li\_%' or x like 'lc\_%' loop
    ov := o->k; nv := n->k;
    if nv is not distinct from ov then continue; end if;
    touched := true;
    if jsonb_typeof(nv) <> 'object' then
      if ov is null then n := n - k; else n := n || jsonb_build_object(k, ov); end if; continue; end if;
    if k like 'lc\_%' then                                   -- comments: added once, never rewritten
      if ov is not null then n := n || jsonb_build_object(k, ov);
      elsif not (editor or (new.coll = 'keep' and jsonb_typeof(o->'assign') = 'array' and o->'assign' ? (me->>'id'))) then
        raise exception 'only the people on this list can comment' using errcode = '42501';
      elsif mats and not prep and not exists (select 1 from jsonb_each(o) e where e.key like 'lc\_%' and coalesce(e.value->>'by','') <> actor) then
        -- material requests: the material office asks, the others answer (Baruch 2026-10-21)
        raise exception 'Menachem starts the conversation on a material request — you can answer him' using errcode = '42501';
      else n := n || jsonb_build_object(k, (nv - 'by') || jsonb_build_object('by', actor, 'ts', coalesce(public._num(nv->>'ts')::bigint, nowms))); end if;
      continue; end if;
    if position('~' in k) > 0 then                           -- a kept copy: only the server makes them; editors may dismiss
      if ov is null then n := n - k; elsif editor then n := n || jsonb_build_object(k, ov || jsonb_build_object('gone', coalesce(nv->'gone','false'::jsonb))); else n := n || jsonb_build_object(k, ov); end if;
      continue; end if;
    if ov is null then                                       -- new item
      if not editor then raise exception 'only the people on this list can add to it' using errcode = '42501'; end if;
      nv := (nv - 'base') || jsonb_build_object('rev', 1, 'by', actor, 'ts', coalesce(public._num(nv->>'ts')::bigint, nowms), 'eby', actor, 'eat', nowms);
      if mats then nv := private.mat_item_fix(null, nv, prep, pick, actor, nowms); end if;
      n := n || jsonb_build_object(k, nv);
      continue; end if;
    orev := coalesce(public._num(ov->>'rev')::int, 0);
    base := public._num(nv->>'base')::int;
    if base is null and coalesce(public._num(nv->>'rev')::int, 0) <= orev and not pick then   -- an older copy sent again: keep the newer one
      n := n || jsonb_build_object(k, ov); continue; end if;
    -- permission: editors change anything; an assignee only ticks off their own item
    if not editor then
      if not (ov->>'to' = me->>'id' and (nv - 'done' - 'doneBy' - 'doneAt' - 'rev' - 'base' - 'eby' - 'eat') = (ov - 'done' - 'doneBy' - 'doneAt' - 'rev' - 'base' - 'eby' - 'eat')) then
        raise exception 'only the people on this list can change this item' using errcode = '42501'; end if;
    end if;
    if base is not null and base < orev then                 -- changed on another phone since this phone saw it: keep both
      ck := k || '~' || actor || '~' || base;
      n := n || jsonb_build_object(k, ov) || jsonb_build_object(ck, (nv - 'base') || jsonb_build_object('conflict', true, 'of', k, 'eby', actor, 'eat', nowms, 'rev', orev));
      continue; end if;
    nv := (nv - 'base' - 'by' - 'ts') || jsonb_build_object('rev', orev + 1, 'eby', actor, 'eat', nowms,
            'by', coalesce(ov->'by', to_jsonb(actor)), 'ts', coalesce(ov->'ts', to_jsonb(nowms)));
    if mats then nv := private.mat_item_fix(ov, nv, prep, pick, actor, nowms); end if;
    -- nothing left to change (e.g. a tick from someone who may not tick): keep the item as it was, same version
    if (nv - 'rev' - 'eby' - 'eat' - 'pqBy' - 'pqAt') = (ov - 'rev' - 'eby' - 'eat' - 'pqBy' - 'pqAt' - 'base') then n := n || jsonb_build_object(k, ov); continue; end if;
    n := n || jsonb_build_object(k, nv);
  end loop;
  -- c) mats: who it is sent to / who else is on it — editors only
  if mats and (n->'to' is distinct from o->'to' or n->'collab' is distinct from o->'collab') and o <> '{}'::jsonb and not editor then
    raise exception 'only the people on this list can send it on' using errcode = '42501'; end if;
  -- d) assignees (server-kept): everyone with an open item on the list
  select coalesce(jsonb_agg(distinct v->>'to'), '[]'::jsonb) into a from jsonb_each(n) e(kk, v)
   where kk like 'li\_%' and position('~' in kk) = 0 and jsonb_typeof(v) = 'object' and coalesce(v->>'to','') <> '' and not coalesce((v->>'gone')::boolean, false);
  if touched or (n->'assign') is distinct from a then n := n || jsonb_build_object('assign', a); end if;
  -- e) an assignee (not an editor) may not change anything else on the list
  if not editor and o <> '{}'::jsonb then
    for fld in select x from jsonb_object_keys(n || o) x where x not like 'li\_%' and x not like 'lc\_%' and x not in ('assign','edited','order') loop
      if n->fld is distinct from o->fld then raise exception 'only the people on this list can change it' using errcode = '42501'; end if;
    end loop;
  end if;
  -- f) material request status
  if mats then
    -- the status the preparer picks (requested / reviewing / ordered / preparing / completed); an older app sets 'status'
    if not prep then n := (n - 'stm') || case when o ? 'stm' then jsonb_build_object('stm', o->'stm') else '{}'::jsonb end;
    elsif n->'stm' is not distinct from o->'stm' and n->>'status' is distinct from o->>'status' and o <> '{}'::jsonb then
      n := n || jsonb_build_object('stm', case n->>'status' when 'delivered' then 'completed' when 'ordered' then 'ordered' else 'requested' end);
    end if;
    if coalesce(n->>'stm','') <> '' and n->>'stm' not in ('requested','reviewing','ordered','preparing','completed') then
      n := (n - 'stm') || case when o ? 'stm' then jsonb_build_object('stm', o->'stm') else '{}'::jsonb end; end if;
    st := private.mat_status(n);
    n := n || jsonb_build_object('st', st, 'status', case when st = 'completed' then 'delivered' when st in ('requested','reviewing') then 'open' else 'ordered' end);
    if st is distinct from o->>'st' then
      n := n || jsonb_build_object('stAt', nowms, 'stBy', actor);
      if st = 'ready' then n := n || jsonb_build_object('readyAt', nowms); end if;
    else
      n := (n - 'stAt' - 'stBy' - 'readyAt') || (select coalesce(jsonb_object_agg(x, o->x), '{}'::jsonb) from unnest(array['stAt','stBy','readyAt']) x where o ? x);
    end if;
    if not srv and o = '{}'::jsonb then n := n || jsonb_build_object('from', coalesce(nullif(n->>'from',''), actor)); end if;
  end if;
  new.data := n;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_ptask()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb; o jsonb; n jsonb := new.data; nowms bigint := (extract(epoch from now())*1000)::bigint; ch boolean; mv boolean; tb jsonb; tl jsonb;
begin
  if current_user not in ('authenticated','anon') or auth.uid() is null then return new; end if;
  if jsonb_typeof(n) <> 'object' then raise exception 'not allowed' using errcode = '42501'; end if;
  me := public.my_emp_data();
  if coalesce(me->>'id','') = '' then raise exception 'not allowed' using errcode = '42501'; end if;
  o := case when tg_op = 'UPDATE' and not old.deleted and jsonb_typeof(old.data) = 'object' then old.data end;
  if new.deleted then raise exception 'a Trello task is finished or archived, not deleted' using errcode = '42501'; end if;
  if o is null then
    if n->>'owner' is distinct from me->>'id' then raise exception 'not allowed' using errcode = '42501'; end if;
    if coalesce(n->>'list','') = '' or coalesce(btrim(n->>'t'),'') = '' then raise exception 'pick a Trello list and type the task' using errcode = '22023'; end if;
    new.data := jsonb_build_object('id', new.id, 'owner', me->>'id', 't', left(n->>'t', 500), 'desc', left(coalesce(n->>'desc',''), 4000),
      'list', n->'list', 'listName', n->'listName', 'board', n->'board', 'boardName', n->'boardName', 'due', n->'due',
      'done', coalesce(n->'done','false'::jsonb), 'push', true, 'eat', nowms, 'eby', me->>'id', 'created', nowms);
    return new;
  end if;
  if o->>'owner' is distinct from me->>'id' then raise exception 'not allowed' using errcode = '42501'; end if;   -- only the person himself
  -- a move: to a list that is really on one of the card owner's boards (any board — job Name's, orders, …)
  if o->>'card' is not null and n ? 'list' and coalesce(n->>'list','') <> '' and n->'list' is distinct from o->'list' then
    select bb, ll into tb, tl from public.records r, jsonb_array_elements(coalesce(r.data->'boards','[]'::jsonb)) bb, jsonb_array_elements(coalesce(bb->'lists','[]'::jsonb)) ll
     where r.coll = 'ptask' and r.id = 'ptmeta_' || (o->>'owner') and not r.deleted and ll->>'id' = n->>'list' limit 1;
  end if;
  mv := tl is not null;
  ch := n->'t' is distinct from o->'t' or n->'desc' is distinct from o->'desc' or n->'done' is distinct from o->'done' or n->'due' is distinct from o->'due'
        or (o->>'card' is null and n->'list' is distinct from o->'list') or mv;
  if not ch then new.data := o || jsonb_build_object('id', new.id); return new; end if;
  new.data := o || jsonb_build_object('t', left(coalesce(n->>'t', o->>'t'), 500), 'desc', left(coalesce(n->>'desc', o->>'desc', ''), 4000),
      'done', coalesce(n->'done', o->'done', 'false'::jsonb), 'due', n->'due', 'push', true, 'eat', nowms, 'eby', me->>'id')
    || case when o->>'card' is null and n ? 'list' then jsonb_build_object('list', n->'list', 'listName', n->'listName', 'board', n->'board', 'boardName', n->'boardName') else '{}'::jsonb end
    || case when mv then jsonb_build_object('list', tl->'id', 'listName', tl->'name', 'board', tb->'id', 'boardName', tb->'name', 'mv', true) else '{}'::jsonb end;
  new.data := (new.data - 'pushErr') || jsonb_build_object('id', new.id);
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_punch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb; role text; owner boolean; payroll boolean; clockok boolean; o jsonb; n jsonb := new.data;
        nowms bigint := (extract(epoch from now()) * 1000)::bigint; hist jsonb; late boolean; why text;
        chg boolean; LATE_MS constant bigint := 30 * 60000;
begin
  if current_user not in ('authenticated','anon') or auth.uid() is null then return new; end if;
  if jsonb_typeof(n) <> 'object' then return new; end if;
  me := public.my_emp_data(); if me = '{}'::jsonb then return new; end if;
  role := coalesce(me->>'role',''); owner := role = 'owner';
  payroll := role = 'office' and me->>'title' = 'Payroll';
  clockok := owner or payroll;
  o := case when tg_op = 'UPDATE' and jsonb_typeof(old.data) = 'object' then old.data end;
  n := (n - 'hist' - 'lateEntry')
       || case when o ? 'lateEntry' then jsonb_build_object('lateEntry', o->'lateEntry') else '{}'::jsonb end;
  hist := case when coalesce(jsonb_typeof(o->'hist'),'') = 'array' then o->'hist' else '[]'::jsonb end;

  if new.deleted then
    if tg_op = 'UPDATE' and old.deleted then new.data := old.data; return new; end if;
    if not clockok then raise exception 'only the owner or Payroll can remove a clock entry' using errcode = '42501'; end if;
    new.data := coalesce(o, n) || jsonb_build_object('deletedBy', me->>'id', 'deletedAt', nowms,
                 'hist', hist || jsonb_build_array(jsonb_build_object('act','deleted','by',me->>'id','at',nowms)));
    return new;
  end if;

  if o is null or old.deleted then
    late := coalesce(public._num(n->>'in'), nowms) < nowms - LATE_MS;
    if n->>'who' is distinct from me->>'id' and not clockok then
      raise exception 'only the owner or Payroll can add a clock entry for someone else' using errcode = '42501'; end if;
    if clockok and (n->>'who' is distinct from me->>'id' or o is not null) then
      why := private.last_why(n);
      if why is null then raise exception 'a reason is required for a clock entry added by the office' using errcode = '42501'; end if;
      hist := hist || jsonb_build_array(jsonb_build_object('act', case when o is null then 'added' else 'restored' end,'by',me->>'id','at',nowms,
                 'in',n->'in','out',n->'out','who',n->'who','why',why));
    elsif late then
      n := n || jsonb_build_object('pending', true,
             'lateEntry', jsonb_build_object('srvIn', nowms, 'in', n->'in', 'out', n->'out', 'site', n->'site', 'by', me->>'id'));
      hist := hist || jsonb_build_array(jsonb_build_object('act','late','by',me->>'id','at',nowms,'in',n->'in','out',n->'out',
                 'minutesLate', round((nowms - public._num(n->>'in')) / 60000.0)));
    else
      hist := hist || jsonb_build_array(jsonb_build_object('act','created','by',me->>'id','at',nowms,'in',n->'in'));
    end if;
    new.data := n || jsonb_build_object('hist', hist);
    return new;
  end if;

  -- A5b close: only Owner/Payroll end someone else's open clock entry (a manager's "not approved" answer to a
  -- "clock me in" request ends it at its own start and is the one exception)
  if coalesce(o->'out','null'::jsonb) = 'null'::jsonb and coalesce(n->'out','null'::jsonb) <> 'null'::jsonb
     and o->>'who' is distinct from me->>'id' and not clockok
     and not (coalesce(o->'pending' = 'true'::jsonb, false) and n->'out' = n->'in') then
    raise exception 'only the owner or Payroll can clock someone else out' using errcode = '42501'; end if;
  if not private.edits_prefix_kept(o->'edits', n->'edits') then
    raise exception 'the change history of a clock entry cannot be rewritten' using errcode = '42501'; end if;
  chg := n->'in' is distinct from o->'in' or n->'who' is distinct from o->'who' or n->'site' is distinct from o->'site'
      or (coalesce(o->'out','null'::jsonb) <> 'null'::jsonb and n->'out' is distinct from o->'out')
      or n->'voided' is distinct from o->'voided'
      or not private.punch_breaks_kept(o, n);
  if chg then
    if not clockok then raise exception 'only the owner or Payroll can change clock times' using errcode = '42501'; end if;
    why := private.last_why(n);
    if why is null or private.arr_len(n->'edits') <= private.arr_len(o->'edits') then
      raise exception 'a reason is required to change clock times' using errcode = '42501'; end if;
    hist := hist || jsonb_build_array(jsonb_build_object('act', case when n ? 'voided' and not (o ? 'voided') then 'voided'
                                                               when o ? 'voided' and not (n ? 'voided') then 'unvoided' else 'edited' end,
              'by',me->>'id','at',nowms,'why',why,
              'from',jsonb_build_object('in',o->'in','out',o->'out','who',o->'who','site',o->'site'),
              'to',jsonb_build_object('in',n->'in','out',n->'out','who',n->'who','site',n->'site')));
  end if;
  if coalesce((o->'pending' = 'true'::jsonb),false) and not coalesce((n->'pending' = 'true'::jsonb),false) then
    if o ? 'lateEntry' then
      if not clockok then raise exception 'only Payroll can approve a late clock entry' using errcode = '42501'; end if;
      if o->>'who' = me->>'id' and not owner then raise exception 'someone else must approve your own clock entry' using errcode = '42501'; end if;
      if coalesce((n->'rejected' = 'true'::jsonb),false) and length(trim(coalesce(n->>'rejectWhy',''))) < 3 then
        raise exception 'a reason is required to reject a clock entry' using errcode = '42501'; end if;
    end if;
    hist := hist || jsonb_build_array(jsonb_build_object('act', case when coalesce((n->'rejected' = 'true'::jsonb),false) then 'rejected' else 'approved' end,
              'by',me->>'id','at',nowms,'why',nullif(trim(coalesce(n->>'rejectWhy','')),'')));
  end if;
  if o ? 'lateEntry' and not clockok and (n->'rejected' is distinct from o->'rejected' or n->'approvedBy' is distinct from o->'approvedBy') then
    raise exception 'only Payroll can approve a late clock entry' using errcode = '42501'; end if;
  new.data := n || jsonb_build_object('hist', hist);
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_rates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb;
begin
  if current_user not in ('authenticated','anon') or auth.uid() is null then return new; end if;
  me := public.my_emp_data();
  if not (me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll')) then
    raise exception 'only the owner or Payroll can change pay rates' using errcode = '42501'; end if;
  if not new.deleted and (jsonb_typeof(new.data) <> 'object' or new.data->>'who' is distinct from new.id
     or (new.data ? 'rate' and new.data->>'rate' is not null and (public._num(new.data->>'rate') is null or public._num(new.data->>'rate') < 0 or public._num(new.data->>'rate') > 500))) then
    raise exception 'bad rate' using errcode = '42501'; end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb; role text; boss boolean; office boolean; payroll boolean; money boolean; hours boolean; approver boolean; material boolean;
        o jsonb; n jsonb := new.data; f text; nowms bigint := (extract(epoch from now()) * 1000)::bigint;
begin
  if current_user not in ('authenticated','anon') or auth.uid() is null then return new; end if;
  if tg_op = 'INSERT' and private.row_exists(new.coll, new.id) then return new; end if;
  me := public.my_emp_data();
  if me = '{}'::jsonb then return new; end if;
  role := coalesce(me->>'role','');
  o := case when tg_op = 'UPDATE' then old.data else null end;
  if new.coll = 'inbox' and tg_op = 'INSERT' and jsonb_typeof(n) = 'object' then
    new.data := n || jsonb_build_object('from', me->>'id'); n := new.data; end if;
  if new.coll = 'push' and ((o is null and n->>'who' is distinct from me->>'id') or (o is not null and o->>'who' is distinct from me->>'id')
                            or (not new.deleted and n->>'who' is distinct from me->>'id')) then
    raise exception 'not allowed' using errcode = '42501'; end if;
  if new.coll = 'emps' and not new.deleted and (
       (n ? 'authUid' and n->>'authUid' is distinct from o->>'authUid' and exists (select 1 from public.records x where x.coll='emps' and not x.deleted and x.id <> new.id and x.data->>'authUid' = n->>'authUid'))
    or (n ? 'authEmail' and lower(n->>'authEmail') is distinct from lower(o->>'authEmail') and exists (select 1 from public.records x where x.coll='emps' and not x.deleted and x.id <> new.id and lower(x.data->>'authEmail') = lower(n->>'authEmail')))) then
    raise exception 'that sign-in already belongs to someone' using errcode = '42501'; end if;
  -- A2 punches: server receive time, set once, never changed by a phone
  if new.coll = 'punches' and jsonb_typeof(n) = 'object' then
    if tg_op = 'INSERT' or old.deleted then new.data := (n - 'srvIn') || jsonb_build_object('srvIn', nowms);
    else new.data := (n - 'srvIn') || case when jsonb_typeof(o) = 'object' and o ? 'srvIn' then jsonb_build_object('srvIn', o->'srvIn') else '{}'::jsonb end; end if;
    n := new.data;
  end if;
  -- A5b keep: fields set by the server or by Payroll survive a phone re-sending an older whole copy
  if new.coll = 'punches' and tg_op = 'UPDATE' and jsonb_typeof(o) = 'object' and jsonb_typeof(n) = 'object'
     and not (role = 'owner' or (role = 'office' and me->>'title' = 'Payroll')) then
    n := n || coalesce((select jsonb_object_agg(k, o->k) from unnest(array['pending','approvedBy','rejected','rejectWhy']) k where o ? k and not n ? k), '{}'::jsonb);
    new.data := n;
  end if;
  if role = 'owner' then return new; end if;
  boss := public.is_boss();
  office := role = 'office';
  payroll := office and me->>'title' = 'Payroll';
  material := office and me->>'title' = 'Material';
  money := coalesce((me->>'all')::boolean,false) or (office and me->>'title' in ('Payroll','Bookkeeper'));
  hours := coalesce((me->>'all')::boolean,false) or payroll;
  approver := role in ('manager','office') or coalesce((me->>'all')::boolean,false);
  if new.coll = 'emps' then
    if boss then
      if public.emp_privileged(n) or coalesce(n->>'role','') = 'office'
         or (o is not null and (public.emp_privileged(o) or coalesce(o->>'role','') = 'office')) then
        if not (o is not null and old.id = me->>'id' and not new.deleted and (n - 'lang' - 'phone') = (o - 'lang' - 'phone')) then
          raise exception 'only the owner can change this person' using errcode = '42501'; end if;
      end if;
      return new;
    end if;
    if new.deleted or o is null or old.id <> me->>'id' or (n - 'lang' - 'phone') is distinct from (o - 'lang' - 'phone') then
      raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll in ('base','crews','sched','_') then
    if not boss then raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll = 'orr' then
    if not (boss or (office and coalesce(me->>'title','') <> 'Accountant')) then raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll = 'sites' then
    if not (boss or office) and (new.deleted
         or n->'lat' is distinct from o->'lat' or n->'lng' is distinct from o->'lng' or n->'rad' is distinct from o->'rad'
         or n->'fenceOk' is distinct from o->'fenceOk' or n->'trip' is distinct from o->'trip'
         or n->'travelPay' is distinct from o->'travelPay') then
      raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll = 'stock' then
    if new.deleted and not (boss or material) then raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll = 'mats' then
    if new.deleted and not (boss or material or o->>'from' = me->>'id') then raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll = 'keep' then
    if o is not null and o->>'owner' is distinct from me->>'id' and (n->>'owner' is distinct from o->>'owner' or new.deleted) then
      raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll = 'jobs' then
    if not boss and ((o is null and coalesce(n->>'from', me->>'id') <> me->>'id') or (o is not null and n->>'from' is distinct from o->>'from')) then
      raise exception 'not allowed' using errcode = '42501'; end if;
    if new.deleted and not boss and o->>'from' is distinct from me->>'id' then raise exception 'not allowed' using errcode = '42501'; end if;
    for f in select k from jsonb_object_keys(n) k where k like 'm\_%' loop
      if (o is null or o->f is distinct from n->f) and n->f->>'by' is distinct from me->>'id'
         and not (o ? f and ((n->f) - 'seen' - 'got') = ((o->f) - 'seen' - 'got')) then
        raise exception 'not allowed' using errcode = '42501'; end if;
    end loop;
    return new;
  end if;
  if new.coll = 'meets' then
    if (o is null and n->>'by' is distinct from me->>'id') or (o is not null and o->>'by' is distinct from me->>'id') then
      raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.coll not in ('punches','timeoff','exps','travel','goHomeLog') then return new; end if;
  if new.coll = 'goHomeLog' then
    if not (role = 'manager' or coalesce((me->>'all')::boolean,false)) then raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if new.deleted then
    if new.coll = 'punches' and not hours then raise exception 'not allowed' using errcode = '42501'; end if;
    if new.coll = 'exps' and not money and (o->>'who' is distinct from me->>'id' or coalesce((o->>'paid')::boolean,false)) then raise exception 'not allowed' using errcode = '42501'; end if;
    if new.coll in ('timeoff','travel') and not boss and o->>'who' is distinct from me->>'id' then raise exception 'not allowed' using errcode = '42501'; end if;
    return new;
  end if;
  if ((o is null and n->>'who' is distinct from me->>'id') or (o is not null and n->>'who' is distinct from o->>'who'))
     and not (new.coll = 'punches' and hours) and not (new.coll = 'exps' and money) and not (new.coll in ('timeoff','travel') and boss) then
    raise exception 'not allowed' using errcode = '42501'; end if;
  if new.coll = 'punches' and not hours then
    if tg_op = 'UPDATE' and old.deleted then raise exception 'only Payroll can bring back a deleted clock entry' using errcode = '42501'; end if;
    if o is not null and not private.punch_breaks_kept(o, n) then raise exception 'breaks can only be changed by Payroll' using errcode = '42501'; end if;
    if o is null and (public._num(n->>'in') is null or public._num(n->>'in') > nowms + 300000 or public._num(n->>'in') < nowms - 3*86400000
                      or (n->'out' is not null and n->'out' <> 'null'::jsonb and (public._num(n->>'out') < public._num(n->>'in') or public._num(n->>'out') > nowms + 300000))) then
      raise exception 'clock time out of range' using errcode = '42501'; end if;
    if coalesce(n->>'approvedBy','') <> coalesce(o->>'approvedBy','')
       or (coalesce((o->>'pending')::boolean,false) and not coalesce((n->>'pending')::boolean,false)) then
      if not approver or o is null or o->>'who' = me->>'id' or (n->>'approvedBy' is distinct from me->>'id' and coalesce(n->>'approvedBy','') <> '') then
        raise exception 'not allowed' using errcode = '42501'; end if;
    end if;
    if o is not null then
      if n->>'in' is distinct from o->>'in' or n->'edits' is distinct from o->'edits' then
        raise exception 'clock times can only be changed by Payroll' using errcode = '42501'; end if;
      if o->'out' is not null and o->'out' <> 'null'::jsonb and n->'out' is distinct from o->'out' then
        raise exception 'clock times can only be changed by Payroll' using errcode = '42501'; end if;
      if (o->'out' is null or o->'out' = 'null'::jsonb) and n->'out' is not null and n->'out' <> 'null'::jsonb then
        if o->>'who' is distinct from me->>'id' and not approver then raise exception 'not allowed' using errcode = '42501'; end if;
        if public._num(n->>'out') > nowms + 300000 or public._num(n->>'out') < public._num(o->>'in') then
          raise exception 'clock time out of range' using errcode = '42501'; end if;
      end if;
    end if;
  elsif new.coll = 'timeoff' and boss and coalesce(n->>'who', o->>'who') = me->>'id'
        and o is not null and n->>'status' is distinct from o->>'status' and n->>'status' in ('approved','denied') then
    raise exception 'your own time off is approved by the owner' using errcode = '42501';
  elsif new.coll = 'timeoff' and not boss then
    if (o is null and coalesce(n->>'status','pending') <> 'pending')
       or (o is not null and n->>'status' is distinct from o->>'status' and n->>'status' <> 'cancelled')
       or (o is not null and coalesce(o->>'status','pending') <> 'pending' and (n - 'status' - 'seen' - 'read') is distinct from (o - 'status' - 'seen' - 'read')) then
      raise exception 'not allowed' using errcode = '42501'; end if;
  elsif new.coll = 'exps' and not money then
    if coalesce((n->>'paid')::boolean,false) and not coalesce((o->>'paid')::boolean,false) then raise exception 'not allowed' using errcode = '42501'; end if;
    if n->>'paidBy' is distinct from o->>'paidBy' or n->>'paidAt' is distinct from o->>'paidAt' then raise exception 'not allowed' using errcode = '42501'; end if;
    if coalesce((o->>'paid')::boolean,false) and (n - 'seen' - 'read') is distinct from (o - 'seen' - 'read') then raise exception 'not allowed' using errcode = '42501'; end if;
  elsif new.coll = 'travel' and (not boss or coalesce(n->>'who', o->>'who') = me->>'id') then
    if o is null or old.deleted then new.data := private.travel_checked(n, new.id); n := new.data; end if;
    if o is not null and (n->>'status' is distinct from o->>'status' or n->>'minutes' is distinct from o->>'minutes' or n->>'pay' is distinct from o->>'pay' or n->>'miles' is distinct from o->>'miles') then
      raise exception 'not allowed' using errcode = '42501'; end if;
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_sched_rev()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if NEW.coll='sched' and OLD.coll='sched' and not coalesce(NEW.deleted,false)
     and (NEW.data is distinct from OLD.data) then
    if coalesce((NEW.data->>'rev')::int,0) <= coalesce((OLD.data->>'rev')::int,0) then
      raise exception 'stale_sched_write for %: incoming rev % must exceed stored rev %',
        NEW.id, coalesce(NEW.data->>'rev','0'), coalesce(OLD.data->>'rev','0')
        using errcode='40001';
    end if;
  end if;
  return NEW;
end $function$
CREATE OR REPLACE FUNCTION public.guard_stock_qty()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user not in ('authenticated','anon') then return new; end if;
  if coalesce(current_setting('app.stock_txn', true), '') = '1' then return new; end if;
  if jsonb_typeof(new.data) <> 'object' then return new; end if;
  if tg_op = 'UPDATE' then
    new.data := (new.data - 'qty' - 'qv' - 'counted' - 'countedBy')
      || case when jsonb_typeof(old.data) = 'object' and old.data ? 'qty' then jsonb_build_object('qty', old.data->'qty') else '{}'::jsonb end
      || case when jsonb_typeof(old.data) = 'object' and old.data ? 'qv' then jsonb_build_object('qv', old.data->'qv') else '{}'::jsonb end
      || case when jsonb_typeof(old.data) = 'object' and old.data ? 'counted' then jsonb_build_object('counted', old.data->'counted') else '{}'::jsonb end
      || case when jsonb_typeof(old.data) = 'object' and old.data ? 'countedBy' then jsonb_build_object('countedBy', old.data->'countedBy') else '{}'::jsonb end;
  else
    new.data := (new.data - 'qty' - 'qv' - 'counted' - 'countedBy') || '{"qty":0}'::jsonb;
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_stocklog()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('authenticated','anon') and coalesce(current_setting('app.stock_txn', true),'') <> '1' then
    raise exception 'movement history is written only by the stock system' using errcode='42501';
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.history_records(p_coll text, p_from bigint, p_to bigint, p_who text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_limit integer DEFAULT 3000)
 RETURNS TABLE(coll text, id text, data jsonb, deleted boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with c as materialized (
    select r.coll, r.id, r.data, r.deleted
      from public.records r
     where p_coll = 'punches' and r.coll = 'punches' and not r.deleted
       and public._num(r.data->>'in') >= p_from and public._num(r.data->>'in') < p_to
       and (p_who is null or r.data->>'who' = p_who)
       and (p_site is null or r.data->>'site' = p_site)
    union all
    select r.coll, r.id, r.data, r.deleted
      from public.records r
     where p_coll = 'travel' and r.coll = 'travel' and not r.deleted
       and (r.data->>'date') >= to_char(to_timestamp(p_from / 1000.0) at time zone 'America/New_York', 'YYYY-MM-DD')
       and (r.data->>'date') <  to_char(to_timestamp(p_to / 1000.0) at time zone 'America/New_York', 'YYYY-MM-DD')
       and (p_who is null or r.data->>'who' = p_who)
       and (p_site is null or r.data->>'site' = p_site)
  )
  select c.coll, c.id, c.data, c.deleted
    from c
   where (select public.is_member())
     and coalesce(public.can_see2(c.coll, c.data, (select public.my_emp_data())), false)
   order by c.id
   limit least(greatest(coalesce(p_limit, 3000), 1), 5000);
$function$
