CREATE OR REPLACE FUNCTION public.labor_hist(p_from bigint, p_to bigint)
 RETURNS TABLE(kind text, who text, wk text, site text, h double precision, n integer, rec jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with p as (
    select r.data d, public._num(r.data->>'in') tin, public._num(r.data->>'out') tout
    from public.records r
    where r.coll = 'punches' and not r.deleted
      and public._num(r.data->>'in') >= p_from and public._num(r.data->>'in') < p_to
      and coalesce(r.data->'rejected', 'null'::jsonb) in ('null'::jsonb, 'false'::jsonb, '0'::jsonb, '""'::jsonb)
      and coalesce(r.data->'pending', 'null'::jsonb) in ('null'::jsonb, 'false'::jsonb, '0'::jsonb, '""'::jsonb)
      and coalesce(r.data->'voided', 'null'::jsonb) in ('null'::jsonb, 'false'::jsonb, '0'::jsonb, '""'::jsonb))
  select 'agg', d->>'who', to_char(dd - extract(dow from dd)::int, 'YYYY-MM-DD'), coalesce(nullif(d->>'site',''),'none'),
         sum(greatest(0, tout - tin) / 3600000.0)::float8, count(*)::int, null::jsonb
  from (select d, tin, tout, (to_timestamp(tin / 1000.0) at time zone 'America/New_York')::date dd from p
        where d->>'src' = 'fingercheck' and tout is not null) x
  group by 2, 3, 4
  union all
  select 'raw', null, null, null, null, null, d from p where coalesce(d->>'src','') <> 'fingercheck';
$function$
CREATE OR REPLACE FUNCTION public.labor_hist2(p_from bigint, p_to bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with p as (
    select r.data d, public._num(r.data->>'in') tin, public._num(r.data->>'out') tout
    from public.records r
    where r.coll = 'punches' and not r.deleted
      and public._num(r.data->>'in') >= p_from and public._num(r.data->>'in') < p_to
      and coalesce(r.data->'rejected', 'null'::jsonb) in ('null'::jsonb, 'false'::jsonb, '0'::jsonb, '""'::jsonb)
      and coalesce(r.data->'pending', 'null'::jsonb) in ('null'::jsonb, 'false'::jsonb, '0'::jsonb, '""'::jsonb)
      and coalesce(r.data->'voided', 'null'::jsonb) in ('null'::jsonb, 'false'::jsonb, '0'::jsonb, '""'::jsonb)),
  a as (
    select d->>'who' who, to_char(dd - extract(dow from dd)::int, 'YYYY-MM-DD') wk, coalesce(nullif(d->>'site',''),'none') site,
           sum(greatest(0, tout - tin))::bigint ms
    from (select d, tin, tout, (to_timestamp(tin / 1000.0) at time zone 'America/New_York')::date dd from p
          where d->>'src' = 'fingercheck' and tout is not null) x
    group by 1, 2, 3)
  select jsonb_build_object(
    'agg', coalesce((select jsonb_agg(jsonb_build_array(who, wk, site, ms)) from a), '[]'::jsonb),
    'raw', coalesce((select jsonb_agg(d) from p where coalesce(d->>'src','') <> 'fingercheck'), '[]'::jsonb));
$function$
CREATE OR REPLACE FUNCTION public.list_history(p_coll text, p_id text)
 RETURNS TABLE(at timestamp with time zone, by_who text, op text, old_data jsonb, new_data jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); d jsonb;
begin
  if p_coll not in ('keep','mats') or me = '{}'::jsonb then return; end if;
  select r.data into d from public.records r where r.coll = p_coll and r.id = p_id;
  if d is null then return; end if;
  if not (private.list_editor(p_coll, d, me) or (p_coll = 'keep' and public.can_see2('keep', d, me))) then return; end if;
  return query select h.at, h.by_who, h.op, h.old_data, h.new_data from public.records_history h
                where h.coll = p_coll and h.id = p_id order by h.at desc, h.hid desc limit 300;
end $function$
CREATE OR REPLACE FUNCTION public.lock_record_key()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('authenticated','anon') and (new.coll is distinct from old.coll or new.id is distinct from old.id) then
    raise exception 'a record cannot be moved' using errcode = '42501';
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.log_client_errors(p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); r jsonb; k int := 0; used int;
begin
  if me = '{}'::jsonb or jsonb_typeof(p_rows) <> 'array' then return 0; end if;
  select coalesce(sum(n),0) into used from private.client_errors where who = me->>'id' and at > now() - interval '1 day';
  if used >= 300 then return 0; end if;
  for r in select value from jsonb_array_elements(p_rows) limit 20 loop
    if jsonb_typeof(r) <> 'object' then continue; end if;
    insert into private.client_errors(who, ver, ua, kind, msg, src, n)
    values (me->>'id', left(coalesce(r->>'ver',''),40), left(coalesce(r->>'ua',''),120), left(coalesce(nullif(r->>'kind',''),'error'),20),
            left(coalesce(r->>'msg',''),500), left(coalesce(r->>'src',''),200), least(greatest(coalesce(public._num(r->>'n')::int,1),1),1000));
    k := k + 1;
  end loop;
  return k;
end $function$
CREATE OR REPLACE FUNCTION public.log_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' and new.data is not distinct from old.data and new.deleted = old.deleted then return null; end if;
  insert into public.records_history (coll, id, op, by_who, old_data, new_data, old_deleted, new_deleted)
  values (new.coll, new.id, lower(tg_op), new.updated_by,
          case when tg_op = 'UPDATE' then old.data end, new.data,
          case when tg_op = 'UPDATE' then old.deleted end, new.deleted);
  return null;
end $function$
CREATE OR REPLACE FUNCTION public.mat_pickup(p_id text, p_txn text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); d jsonb; ln jsonb; it jsonb; k text; qn numeric; moves jsonb := '[]'::jsonb; res jsonb := null;
        nowms bigint := (extract(epoch from now())*1000)::bigint; pkk text; upd jsonb := '{}'::jsonb; rec jsonb := '[]'::jsonb;
begin
  if coalesce(me->>'id','') = '' then raise exception 'not allowed' using errcode = '42501'; end if;
  if coalesce(p_txn,'') !~ '^[A-Za-z0-9_-]{6,80}$' then raise exception 'bad pickup id' using errcode = '22023'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'nothing to pick up' using errcode = '22023'; end if;
  pkk := 'pu_' || p_txn;
  select data into d from public.records where coll = 'mats' and id = p_id and not deleted for update;
  if d is null then raise exception 'that material list is not there' using errcode = '22023'; end if;
  -- only the material office (Menachem) takes material out of the garage count (Baruch 2026-10-21); the owner can too
  if not (me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Material')) then
    raise exception 'only Menachem (material office) can confirm a pickup or delivery' using errcode = '42501'; end if;
  if d ? pkk then return jsonb_build_object('ok', true, 'duplicate', true); end if;
  for ln in select value from jsonb_array_elements(p_lines) loop
    k := ln->>'k'; it := d->k; qn := public._num(ln->>'n');
    if coalesce(k,'') !~ '^li_[^~]+$' or jsonb_typeof(it) <> 'object' or coalesce((it->>'gone')::boolean, false) then
      raise exception 'that item is not on the list' using errcode = '22023'; end if;
    if qn is null or qn <= 0 then raise exception 'how many were picked up?' using errcode = '22023'; end if;
    if coalesce((ln->>'g')::boolean, false) and coalesce(it->>'sid','') <> '' then
      moves := moves || jsonb_build_array(jsonb_build_object('id', it->>'sid', 'delta', -qn, 'name', it->>'t'));
    end if;
    upd := upd || jsonb_build_object(k, it || jsonb_build_object('pk', coalesce(public._num((upd->k)->>'pk'), public._num(it->>'pk'), 0) + qn,
                                                                 'rev', coalesce(public._num(it->>'rev')::int, 0) + 1, 'eby', me->>'id', 'eat', nowms));
    rec := rec || jsonb_build_array(jsonb_build_object('k', k, 'n', qn, 'g', coalesce((ln->>'g')::boolean, false) and coalesce(it->>'sid','') <> '', 'sid', it->>'sid', 't', it->>'t'));
  end loop;
  if jsonb_array_length(moves) > 0 then
    res := public.apply_stock_txn(jsonb_build_object('id', p_txn, 'kind', 'out', 'site', d->>'site', 'moves', moves, 'ts', nowms,
                                                     'reason', 'Material list pickup', 'src', 'mat:' || p_id));
  end if;
  perform set_config('app.mat_pickup', '1', true);
  update public.records set data = data || upd || jsonb_build_object(pkk, jsonb_build_object('by', me->>'id', 'ts', nowms, 'lines', rec)),
         updated_by = me->>'id', updated_at = now()
   where coll = 'mats' and id = p_id;
  perform set_config('app.mat_pickup', '', true);
  return jsonb_build_object('ok', true, 'duplicate', false, 'stock', res);
end $function$
CREATE OR REPLACE FUNCTION public.meeting_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m record; who text; n int := 0; nowms bigint := (extract(epoch from now())*1000)::bigint; tm text; mins int; msg text; nid text;
begin
  for m in
    select r.id, r.data, s.data->>'name' as site
    from records r left join records s on s.coll='sites' and s.id = r.data->>'site' and not s.deleted
    where r.coll='meets' and not r.deleted
      and (r.data->>'at') ~ '^[0-9]+$'
      and (r.data->>'at')::bigint > nowms
      and (r.data->>'at')::bigint <= nowms + 30*60*1000
      and coalesce(r.data->>'ping15','') <> (r.data->>'at')
  loop
    tm := to_char(to_timestamp((m.data->>'at')::bigint/1000) at time zone 'America/New_York', 'FMHH12:MI AM');
    mins := greatest(1, round(((m.data->>'at')::bigint - nowms)/60000.0))::int;
    for who in
      select distinct x from (
        select m.data->>'by' as x
        union select jsonb_array_elements_text(m.data->'with') where jsonb_typeof(m.data->'with') = 'array'
        union select id from records where not (m.data ? 'with') and coll='emps' and not deleted and data->>'role'='owner' and coalesce((data->>'inactive')::boolean,false)=false
      ) q where x is not null and x <> ''
    loop
      msg := '⏰ ' || tm || case when coalesce(private.emp_row(who)->>'lang','') = 'es' then ' (en ' || mins || ' min): ' || coalesce(m.data->>'title','Reunión')
                                  else ' (in ' || mins || ' min): ' || coalesce(m.data->>'title','Meeting') end || coalesce(' — ' || m.site, '');
      nid := 'n' || replace(gen_random_uuid()::text,'-','');
      insert into records (coll,id,data,deleted,updated_by,updated_at)
      values ('inbox', nid, jsonb_build_object('id',nid,'to',who,'msg',msg,'kind','info','ts',nowms,'read',false,'link',jsonb_build_object('tab','cal','meet',m.id)), false, 'server', now());
      n := n + 1;
    end loop;
    update records set data = data || jsonb_build_object('ping15', m.data->>'at'), updated_at = now() where coll='meets' and id = m.id;
  end loop;
  return n;
end $function$
