CREATE OR REPLACE FUNCTION public.notify_assign()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb; actor text; aname text; n jsonb := new.data; o jsonb := '{}'::jsonb; who text; e jsonb; site text; d text;
        pri boolean; en text; es text; office boolean; isnew boolean; day date; tdy date := (now() at time zone 'America/New_York')::date;
        crew text; sig_o text; sig_n text; txt text; k text; tl text; endm int; ong text;
begin
  if auth.uid() is null then return null; end if;
  if new.coll = 'sched' and new.deleted then n := '{}'::jsonb;
  elsif new.deleted or jsonb_typeof(n) <> 'object' then return null; end if;
  if tg_op = 'UPDATE' and not old.deleted and jsonb_typeof(old.data) = 'object' then o := old.data; end if;
  isnew := o = '{}'::jsonb;
  begin
    me := public.my_emp_data(); actor := me->>'id'; aname := coalesce(nullif(private.emp_row(actor)->>'name', ''), 'Office');

    if new.coll = 'jobs' then
      if coalesce(n->>'status', '') = 'done' then return null; end if;
      pri := coalesce((n->>'pri')::boolean, false); site := private.short_site(n->>'site');
      for who in select x from private.expand_people(n->'to') x except select y from private.expand_people(o->'to') y loop
        e := private.emp_row(who); office := e->>'role' = 'office';
        d := case when coalesce(n->>'descLang', '') = '' or n->>'descLang' = coalesce(e->>'lang', 'en') or coalesce(n->>'descTr', '') = ''
                  then coalesce(n->>'desc', '') else n->>'descTr' end;
        en := case when pri then '🔴 PRIORITY — ' else '' end
              || case when isnew then case when office then 'New task from ' else 'New job from ' end else 'Moved to you by ' end
              || aname || ': ' || case when site <> '' then site || ' — ' else '' end || left(d, 60);
        es := case when pri then '🔴 PRIORIDAD — ' else '' end
              || case when isnew then case when office then 'Nueva tarea de ' else 'Nuevo trabajo de ' end else 'Te lo pasó ' end
              || aname || ': ' || case when site <> '' then site || ' — ' else '' end || left(d, 60);
        perform private.notify_now(who, en, es, case when pri then 'pri' else 'info' end, jsonb_build_object('job', new.id), actor);
      end loop;
      if not isnew then
        for who in select y from private.expand_people(o->'to') y except select x from private.expand_people(n->'to') x loop
          e := private.emp_row(who);
          d := case when coalesce(n->>'descLang', '') = '' or n->>'descLang' = coalesce(e->>'lang', 'en') or coalesce(n->>'descTr', '') = ''
                    then coalesce(n->>'desc', '') else n->>'descTr' end;
          perform private.notify_now(who, 'Taken off your list: ' || case when site <> '' then site || ' — ' else '' end || left(d, 50),
                                          'Quitado de tu lista: ' || case when site <> '' then site || ' — ' else '' end || left(d, 50),
                                          'info', jsonb_build_object('tab', 'jobs'), actor);
        end loop;
      end if;

    elsif new.coll = 'tickets' then
      if coalesce(n->>'to', '') <> '' and n->>'to' is distinct from o->>'to' and coalesce(n->>'status', '') <> 'done' then
        site := coalesce(nullif(private.short_site(n->>'site'), ''), n->>'addr', '');
        pri := coalesce((n->>'pri')::boolean, false);
        perform private.notify_now(n->>'to',
          case when pri then '🔴 ' else '' end || '🔧 Service call for you: ' || site || ' — ' || left(coalesce(n->>'issue', ''), 50),
          case when pri then '🔴 ' else '' end || '🔧 Llamada de servicio para ti: ' || site || ' — ' || left(coalesce(n->>'issue', ''), 50),
          case when pri then 'pri' else 'info' end, jsonb_build_object('svc', new.id), actor);
      end if;

    elsif new.coll = 'sites' then
      site := split_part(coalesce(n->>'name', ''), ',', 1);
      if coalesce(n->>'crew', '') <> '' and n->>'crew' is distinct from o->>'crew' then
        for who in select x from private.expand_people(jsonb_build_array(n->>'crew')) x loop
          perform private.notify_now(who, '📁 Your crew now has ' || site || ' — plans and files are in the job folder',
                                          '📁 Tu cuadrilla ahora tiene ' || site || ' — los planos y archivos están en la carpeta del trabajo',
                                          'info', jsonb_build_object('site', new.id), actor);
        end loop;
      end if;
      if coalesce(o->>'crew', '') <> '' and n->>'crew' is distinct from o->>'crew' then
        crew := private.crew_name(n->>'crew');
        for who in select x from private.expand_people(jsonb_build_array(o->>'crew')) x except select y from private.expand_people(jsonb_build_array(n->>'crew')) y loop
          perform private.notify_now(who,
            '📁 ' || site || case when crew <> '' then ' moved to ' || crew else ' is no longer with your crew' end,
            '📁 ' || site || case when crew <> '' then ' pasó a ' || crew else ' ya no está con tu cuadrilla' end,
            'info', jsonb_build_object('tab', 'sites'), actor);
        end loop;
      end if;

    elsif new.coll = 'emps' then
      if not isnew and coalesce(n->>'crew', '') <> '' and n->>'crew' is distinct from o->>'crew' then
        crew := private.crew_name(n->>'crew');
        perform private.notify_now(new.id, '👷 You are now on ' || crew || ' (' || aname || ')', '👷 Ahora estás en ' || crew || ' (' || aname || ')',
                                   'info', jsonb_build_object('tab', 'punch'), actor);
      end if;

    elsif new.coll = 'sched' then
      sig_o := private.sched_sig(o); sig_n := private.sched_sig(n);
      if sig_o = sig_n then return null; end if;
      k := new.id;
      if k ~ '^ONG:' then
        crew := split_part(k, ':', 2);
        if n = '{}'::jsonb then n := o || jsonb_build_object('to', to_char(tdy, 'YYYY-MM-DD')); end if;   -- removed rule = ends today
        if coalesce(n->>'to', '') <> '' and n->>'to' ~ '^\d{4}-\d{2}-\d{2}$' then
          if (n->>'to')::date < tdy then return null; end if;
          -- Baruch 11/22: a new "every workday" job took over in the same save → its own message says it (one line, not three)
          if exists (select 1 from public.records r where r.coll = 'sched' and not r.deleted and r.id like 'ONG:' || crew || ':%' and r.id <> k
                       and r.updated_at > now() - interval '2 minutes' and coalesce(r.data->>'to','') = '') then return null; end if;
          en := '♾ Ongoing job at ' || private.short_site(n->>'site') || ' ends after ' || private.day_label((n->>'to')::date, 'en');
          es := '♾ El trabajo fijo en ' || private.short_site(n->>'site') || ' termina después del ' || private.day_label((n->>'to')::date, 'es');
        else
          day := case when coalesce(n->>'from', '') ~ '^\d{4}-\d{2}-\d{2}$' then greatest((n->>'from')::date, tdy) else tdy end;
          endm := public._num(n->>'end')::int;
          tl := case when endm is not null and endm <> 1140 then private.min_label(endm::text) end;   -- Baruch 11/22: its own go-home time
          en := '♾ Every working day from ' || private.day_label(day, 'en') || ': ' || private.short_site(n->>'site') || ' ' || private.min_label(n->>'start') || coalesce(' · till ' || tl, '');
          es := '♾ Cada día laboral desde ' || private.day_label(day, 'es') || ': ' || private.short_site(n->>'site') || ' ' || private.min_label(n->>'start') || coalesce(' · hasta las ' || tl, '');
        end if;
        for who in select x from private.expand_people(jsonb_build_array(crew)) x loop
          if who <> coalesce(actor, '') then
            insert into private.notify_queue(to_id, qkey, actor, en, es, sig_before, sig_after, link)
            values (who, k, actor, en, es, sig_o, sig_n, jsonb_build_object('tab', 'sched'));
          end if;
        end loop;
        return null;
      end if;
      if split_part(k, '|', 2) !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
      day := split_part(k, '|', 2)::date;
      if day < tdy or day > tdy + 21 then return null; end if;
      txt := private.sched_text(n);
      -- Baruch 11/22: say until when — the last job's end, else the normal end of that day
      select max(public._num(a->>'end'))::int into endm
        from jsonb_array_elements(case when jsonb_typeof(n->'assignments') = 'array' then n->'assignments' else '[]'::jsonb end) a
       where coalesce(a->>'site','') <> '';
      tl := private.min_label(coalesce(endm, case when extract(dow from day) = 5 then 795 else 1140 end)::text);
      if k ~ '^L:' then
        who := substr(split_part(k, '|', 1), 3);
        en := private.day_label(day, 'en') || ': ' || case when txt <> '' then 'you are moved to ' || txt || ' · till ' || tl else 'your move was cancelled — you are back with your crew' end;
        es := private.day_label(day, 'es') || ': ' || case when txt <> '' then 'te mueven a ' || txt || ' · hasta las ' || tl else 'se canceló tu cambio — vuelves con tu cuadrilla' end;
        if who <> coalesce(actor, '') then
          insert into private.notify_queue(to_id, qkey, actor, en, es, sig_before, sig_after, link)
          values (who, k, actor, en, es, sig_o, sig_n, jsonb_build_object('tab', 'sched'));
        end if;
      else
        crew := split_part(k, '|', 1);
        if n = '{}'::jsonb then
          -- the day's own booking was removed: a new "every workday" job just took over → its message covers it
          if exists (select 1 from public.records r where r.coll = 'sched' and not r.deleted and r.id like 'ONG:' || crew || ':%'
                       and r.updated_at > now() - interval '2 minutes') then return null; end if;
          ong := private.clock_sched_site_ong(crew, day::text);
          if ong is not null then
            en := private.day_label(day, 'en') || ': back to the regular job — ' || private.short_site(ong);
            es := private.day_label(day, 'es') || ': vuelven al trabajo fijo — ' || private.short_site(ong);
          else
            en := private.day_label(day, 'en') || ': no job booked for your crew';
            es := private.day_label(day, 'es') || ': no hay trabajo para tu cuadrilla';
          end if;
        elsif coalesce(n->'cancel','[]'::jsonb) @> '["ONG"]'::jsonb and txt = ''
              and coalesce(n->'replace','{}'::jsonb) in ('{}'::jsonb, 'null'::jsonb) then
          -- a cleared day (✕ on the last job)
          en := private.day_label(day, 'en') || ': no job booked for your crew';
          es := private.day_label(day, 'es') || ': no hay trabajo para tu cuadrilla';
        else
          if coalesce(n->>'cancel','') <> '' or coalesce(n->>'replace','') <> '' or n ? 'patch' then txt := ''; end if;
          en := private.day_label(day, 'en') || ': ' || case when txt <> '' then txt || ' · till ' || tl else 'schedule changed — open the app' end;
          es := private.day_label(day, 'es') || ': ' || case when txt <> '' then txt || ' · hasta las ' || tl else 'el horario cambió — abre la app' end;
          -- chg:1118 name the new job(s) and time
          site := null; d := null;
          select string_agg(private.short_site(x.s) || case when coalesce(private.min_label(x.st),'') <> '' then ' at ' || private.min_label(x.st) else '' end, ' + '
                            order by case when x.st ~ '^[0-9.]+$' then x.st::numeric end nulls last),
                 string_agg(private.short_site(x.s) || case when coalesce(private.min_label(x.st),'') <> '' then ' a las ' || private.min_label(x.st) else '' end, ' + '
                            order by case when x.st ~ '^[0-9.]+$' then x.st::numeric end nulls last)
            into site, d
            from (select a->>'site' s, a->>'start' st
                    from jsonb_array_elements(case when jsonb_typeof(n->'assignments') = 'array' then n->'assignments' else '[]'::jsonb end) a
                   where coalesce(a->>'site','') <> ''
                     and not exists (select 1 from jsonb_array_elements(case when jsonb_typeof(o->'assignments') = 'array' then o->'assignments' else '[]'::jsonb end) b
                                      where b->>'site' = a->>'site' and (b->>'start') is not distinct from (a->>'start'))
                  union all
                  select v->>'site', v->>'start'
                    from jsonb_each(case when jsonb_typeof(n->'replace') = 'object' then n->'replace' else '{}'::jsonb end) r(k2, v)
                   where coalesce(v->>'site','') <> '' and (o->'replace'->k2) is distinct from v) x
           where coalesce(private.short_site(x.s),'') <> '';
          if coalesce(site,'') <> '' and en like '%open the app' then
            en := private.day_label(day, 'en') || ': change — go to ' || site;
            es := private.day_label(day, 'es') || ': cambio — vayan a ' || d;
          end if;
        end if;
        for who in select x from private.expand_people(jsonb_build_array(crew)) x loop
          if who <> coalesce(actor, '') then
            insert into private.notify_queue(to_id, qkey, actor, en, es, sig_before, sig_after, link)
            values (who, k, actor, en, es, sig_o, sig_n, jsonb_build_object('tab', 'sched'));
          end if;
        end loop;
      end if;
    end if;
  exception when others then
    raise warning 'notify_assign % %: %', new.coll, new.id, sqlerrm;
  end;
  return null;
end $function$
CREATE OR REPLACE FUNCTION public.notify_flush()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; n int := 0; parts_en text; parts_es text; cnt int; ids bigint[];
begin
  for r in
    select to_id from private.notify_queue where sent is null and qkey not like 'LIST:%' group by to_id having max(created) < now() - interval '40 seconds'
  loop
    with q as (select * from private.notify_queue where sent is null and to_id = r.to_id and qkey not like 'LIST:%'),
         firsts as (select distinct on (qkey) qkey, sig_before from q order by qkey, created, id),
         lasts as (select distinct on (qkey) qkey, en, es, sig_after, created from q order by qkey, created desc, id desc),
         chg as (select l.* from lasts l join firsts f using (qkey) where coalesce(f.sig_before, '') is distinct from coalesce(l.sig_after, ''))
    select count(*), string_agg(en, ' · ' order by qkey), string_agg(es, ' · ' order by qkey), (select array_agg(id) from q)
      into cnt, parts_en, parts_es, ids from chg;
    if ids is null then select array_agg(id) into ids from private.notify_queue where sent is null and to_id = r.to_id and qkey not like 'LIST:%'; end if;
    if cnt = 1 then
      perform private.notify_now(r.to_id, '📅 Schedule · ' || parts_en, '📅 Horario · ' || parts_es, 'info', jsonb_build_object('tab', 'sched'), null);
      n := n + 1;
    elsif cnt > 1 then
      perform private.notify_now(r.to_id, left('📅 Your schedule changed (' || cnt || '): ' || parts_en, 400),
                                          left('📅 Tu horario cambió (' || cnt || '): ' || parts_es, 400), 'info', jsonb_build_object('tab', 'sched'), null);
      n := n + 1;
    end if;
    update private.notify_queue set sent = now() where id = any(ids);
  end loop;
  return n + private.list_flush();
end $function$
CREATE OR REPLACE FUNCTION public.notify_lists()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb; actor text; aname text; o jsonb := '{}'::jsonb; n jsonb := new.data; k text; ov jsonb; nv jsonb; who text;
        en text[] := '{}'; es text[] := '{}'; it text; title text; ttl_es text; link jsonb; qk text; newto text[] := '{}'; i int;
        stl_en text; stl_es text; qn text; site text; nitems int;
begin
  if auth.uid() is null or new.deleted or jsonb_typeof(n) <> 'object' then return null; end if;
  if new.coll = 'keep' and coalesce(n->>'type','') <> 'punch' then return null; end if;
  if new.coll = 'mats' and tg_op = 'INSERT' then return null; end if;   -- a new request already tells the material office (app message)
  if tg_op = 'UPDATE' and not old.deleted and jsonb_typeof(old.data) = 'object' then o := old.data; end if;
  begin
    me := public.my_emp_data(); actor := me->>'id'; aname := split_part(coalesce(nullif(private.emp_row(actor)->>'name', ''), 'Office'), ' ', 1);
    for k in select x from jsonb_object_keys(n) x where (x like 'li\_%' or x like 'lc\_%') order by x loop
      ov := o->k; nv := n->k;
      if nv is not distinct from ov or jsonb_typeof(nv) <> 'object' then continue; end if;
      qn := coalesce(nullif(nv->>'q',''), '');
      it := left(coalesce(case when qn <> '' then qn || coalesce(' ' || nullif(nv->>'u',''), '×') || ' ' else '' end || (nv->>'t'), nv->>'text', ''), 60);
      if k like 'lc\_%' then en := en || ('💬 ' || left(coalesce(nv->>'text',''), 60)); es := es || ('💬 ' || left(coalesce(nv->>'text',''), 60)); continue; end if;
      if position('~' in k) > 0 then
        if ov is null then en := en || ('⚠ ' || it || ' — changed on two phones at once, both kept'); es := es || ('⚠ ' || it || ' — cambiado en dos teléfonos a la vez, se guardaron ambos'); end if;
        continue; end if;
      if ov is null then
        en := en || ('+ ' || it || case when coalesce((nv->>'cu')::boolean,false) then ' (custom)' else '' end);
        es := es || ('+ ' || it || case when coalesce((nv->>'cu')::boolean,false) then ' (especial)' else '' end);
        if coalesce(nv->>'to','') <> '' then newto := newto || (nv->>'to'); end if;
        continue; end if;
      if coalesce((nv->>'gone')::boolean,false) and not coalesce((ov->>'gone')::boolean,false) then
        en := en || ('− ' || it || ' (removed)'); es := es || ('− ' || it || ' (quitado)'); continue; end if;
      if new.coll = 'mats' and coalesce(public._num(nv->>'pk'),0) > coalesce(public._num(ov->>'pk'),0) then
        en := en || ('📤 picked up ' || (coalesce(public._num(nv->>'pk'),0) - coalesce(public._num(ov->>'pk'),0))::text || ' of ' || it);
        es := es || ('📤 recogido ' || (coalesce(public._num(nv->>'pk'),0) - coalesce(public._num(ov->>'pk'),0))::text || ' de ' || it); continue; end if;
      if new.coll = 'mats' and coalesce((nv->>'rck')::boolean,false) and not coalesce((ov->>'rck')::boolean,false) then
        en := en || ('⚠ ' || it || ' — changed after it was prepared, please recheck');
        es := es || ('⚠ ' || it || ' — cambió después de prepararlo, revisar de nuevo'); continue; end if;
      if coalesce((nv->>'done')::boolean,false) and not coalesce((ov->>'done')::boolean,false) then
        en := en || ('✓ ' || it || case when new.coll = 'mats' then ' — ready' else '' end);
        es := es || ('✓ ' || it || case when new.coll = 'mats' then ' — listo' else '' end); continue; end if;
      if not coalesce((nv->>'done')::boolean,false) and coalesce((ov->>'done')::boolean,false) then
        en := en || ('↺ ' || it || case when new.coll = 'mats' then ' (not ready)' else ' (reopened)' end);
        es := es || ('↺ ' || it || case when new.coll = 'mats' then ' (no listo)' else ' (reabierto)' end); continue; end if;
      if new.coll = 'mats' and nv->'pq' is distinct from ov->'pq' and coalesce(public._num(nv->>'q'),0) > 0 then
        en := en || ('◐ ' || coalesce(public._num(nv->>'pq'),0)::text || ' of ' || it || ' ready');
        es := es || ('◐ ' || coalesce(public._num(nv->>'pq'),0)::text || ' de ' || it || ' listos'); continue; end if;
      if coalesce(nv->>'q','') is distinct from coalesce(ov->>'q','') then
        en := en || (coalesce(nv->>'t','') || ' (qty ' || coalesce(nullif(ov->>'q',''),'—') || ' → ' || coalesce(nullif(nv->>'q',''),'—') || ')');
        es := es || (coalesce(nv->>'t','') || ' (cant. ' || coalesce(nullif(ov->>'q',''),'—') || ' → ' || coalesce(nullif(nv->>'q',''),'—') || ')'); continue; end if;
      if coalesce(nv->>'to','') is distinct from coalesce(ov->>'to','') then
        en := en || ('👤 ' || it || ' → ' || coalesce(nullif(split_part(private.emp_row(nv->>'to')->>'name',' ',1),''),'nobody'));
        es := es || ('👤 ' || it || ' → ' || coalesce(nullif(split_part(private.emp_row(nv->>'to')->>'name',' ',1),''),'nadie'));
        if coalesce(nv->>'to','') <> '' then newto := newto || (nv->>'to'); end if; continue; end if;
      if coalesce(nv->>'t','') is distinct from coalesce(ov->>'t','') or coalesce(nv->>'desc','') is distinct from coalesce(ov->>'desc','')
         or coalesce(nv->>'u','') is distinct from coalesce(ov->>'u','') then en := en || ('✎ ' || it); es := es || ('✎ ' || it); end if;
    end loop;
    if new.coll = 'mats' and coalesce(n->>'to','') <> '' and n->>'to' is distinct from o->>'to' then
      en := en || ('📨 sent to ' || split_part(coalesce(private.emp_row(n->>'to')->>'name','?'),' ',1));
      es := es || ('📨 enviado a ' || split_part(coalesce(private.emp_row(n->>'to')->>'name','?'),' ',1));
    end if;
    if new.coll = 'mats' and coalesce(n->>'st','') is distinct from coalesce(o->>'st','') and o <> '{}'::jsonb
       and n->>'st' in ('reviewing','ordered','preparing','partpicked','completed') then
      stl_en := case n->>'st' when 'reviewing' then 'Reviewing' when 'ordered' then 'Ordered' when 'preparing' then 'Preparing'
                              when 'partpicked' then 'Partially picked up' else 'Completed' end;
      stl_es := case n->>'st' when 'reviewing' then 'En revisión' when 'ordered' then 'Pedido' when 'preparing' then 'Preparando'
                              when 'partpicked' then 'Recogido en parte' else 'Completado' end;
      en := en || ('Status: ' || stl_en); es := es || ('Estado: ' || stl_es);
    end if;
    if new.coll = 'keep' then
      title := '📋 ' || coalesce(nullif(n->>'title',''), 'Punch list'); ttl_es := '📋 ' || coalesce(nullif(n->>'title',''), 'Lista de pendientes');
      link := jsonb_build_object('keep', new.id);
    else
      site := nullif(coalesce(private.short_site(n->>'site'), ''), '');
      if site is null and coalesce(n->>'addr','') <> '' then site := left(n->>'addr', 40); end if;
      title := '📦 Materials' || coalesce(' · ' || site, ''); ttl_es := '📦 Materiales' || coalesce(' · ' || site, '');
      link := jsonb_build_object('mat', new.id);
      -- everything is prepared → tell whoever asked for it right away (once per time it becomes ready)
      if n->>'st' = 'ready' and coalesce(o->>'st','') <> 'ready' and o <> '{}'::jsonb then
        select count(*) into nitems from jsonb_each(n) e where e.key like 'li\_%' and position('~' in e.key) = 0 and jsonb_typeof(e.value) = 'object' and not coalesce((e.value->>'gone')::boolean,false);
        perform private.notify_now(n->>'from', '📦 Your material order is ready.' || coalesce(' — ' || site, '') || ' (' || nitems || ' items, prepared by ' || aname || ')',
                                   '📦 Tu pedido de material está listo.' || coalesce(' — ' || site, '') || ' (' || nitems || ' artículos, preparado por ' || aname || ')',
                                   'mat', link, actor);
      end if;
    end if;
    if coalesce(array_length(en, 1), 0) = 0 then return null; end if;
    qk := 'LIST:' || new.coll || ':' || new.id;
    for who in select p from private.list_people(new.coll, n) p union select unnest(newto) loop
      if who = coalesce(actor, '') then continue; end if;
      for i in 1 .. array_length(en, 1) loop
        insert into private.notify_queue(to_id, qkey, actor, en, es, sig_before, sig_after, link)
        values (who, qk, actor, aname || ': ' || en[i], aname || ': ' || es[i], null, null,
                link || jsonb_build_object('title', title, 'title_es', ttl_es));
      end loop;
    end loop;
  exception when others then
    raise warning 'notify_lists % %: %', new.coll, new.id, sqlerrm;
  end;
  return null;
end $function$
CREATE OR REPLACE FUNCTION public.on_record_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare base text; secret text;
begin
  if new.deleted or new.coll not in ('inbox','sites') then return new; end if;
  if new.coll = 'inbox' and tg_op <> 'INSERT' then return new; end if;
  if new.coll = 'sites' and (tg_op <> 'UPDATE' or coalesce(new.data->>'stage','') = coalesce(old.data->>'stage','') or coalesce(new.data->>'trello','') = '') then return new; end if;
  select v into base from public.server_config where k = 'functions_url';
  select v into secret from public.server_config where k = 'secret';
  if base is null or secret is null then return new; end if;
  if new.coll = 'inbox' then
    perform net.http_post(url := base || '/notify',
      body := jsonb_build_object('to', new.data->>'to', 'msg', new.data->>'msg', 'id', new.id,
                                 'ts', case when (new.data->>'ts') ~ '^[0-9]+$' then (new.data->>'ts')::bigint end),
      headers := jsonb_build_object('Content-Type','application/json','x-push-secret', secret));
  else
    perform net.http_post(url := base || '/trello',
      body := jsonb_build_object('card', new.data->>'trello', 'stage', new.data->>'stage', 'phase', new.data->>'phase'),
      headers := jsonb_build_object('Content-Type','application/json','x-push-secret', secret));
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.ot_back(p_who text, p_site text, p_at bigint)
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select private.back_on_job(p_who, p_site, p_at, 'tracker') $function$
CREATE OR REPLACE FUNCTION public.ot_batt(p_who text, p_batt integer, p_bs integer, p_at bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  update private.ot_tokens set batt = greatest(0, least(100, p_batt)), bs = p_bs, batt_at = to_timestamp(p_at/1000.0)
   where who = p_who and (batt_at is null or batt_at <= to_timestamp(p_at/1000.0));
end $function$
CREATE OR REPLACE FUNCTION public.ot_check(p_who text, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare r private.ot_tokens;
begin
  select * into r from private.ot_tokens where who = p_who;
  if not found or r.token <> p_token or r.accepted_at is null then return jsonb_build_object('ok', false); end if;
  update private.ot_tokens set last_at = now() where who = p_who;
  return jsonb_build_object('ok', true, 'wp', r.wp_hash);
end $function$
CREATE OR REPLACE FUNCTION public.ot_due(p_before bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare r jsonb;
begin
  delete from private.ot_pending where src = 'loc' and coalesce(last_at, at) - at < 240000 and at < p_before - 3300000;
  with d as (delete from private.ot_pending where at <= p_before and (src = 'region' or coalesce(last_at, at) - at >= 240000) returning who, site, at, lat, lng)
  select coalesce(jsonb_agg(to_jsonb(d)), '[]'::jsonb) into r from d;
  return r;
end $function$
CREATE OR REPLACE FUNCTION public.ot_mode(p_who text, p_m integer, p_at bigint)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update private.ot_tokens set mode = p_m, mode_at = to_timestamp(p_at/1000.0)
   where who = p_who and (mode_at is null or mode_at <= to_timestamp(p_at/1000.0)) $function$
CREATE OR REPLACE FUNCTION public.ot_note(p_who text, p_kind text, p_site text, p_at bigint, p_note text, p_wp text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  if p_kind is not null then
    insert into private.ot_events(who, at, kind, site, note) values (p_who, to_timestamp(p_at/1000.0), p_kind, p_site, left(p_note, 300));
    update private.ot_tokens set last_kind = p_kind where who = p_who; end if;
  if p_wp is not null then update private.ot_tokens set wp_hash = p_wp where who = p_who; end if;
end $function$
CREATE OR REPLACE FUNCTION public.ot_pend(p_who text, p_site text, p_at bigint, p_lat double precision, p_lng double precision, p_src text DEFAULT 'region'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  if p_at is null then delete from private.ot_pending where who = p_who and (site = p_site or p_site = '*');
  else insert into private.ot_pending(who, site, at, lat, lng, src, last_at) values (p_who, p_site, p_at, p_lat, p_lng, coalesce(p_src, 'region'), p_at)
       on conflict (who) do update set
         at = case when private.ot_pending.site = excluded.site then least(private.ot_pending.at, excluded.at) else excluded.at end,
         last_at = case when private.ot_pending.site = excluded.site then greatest(coalesce(private.ot_pending.last_at, private.ot_pending.at), excluded.at) else excluded.at end,
         src = case when private.ot_pending.site = excluded.site and private.ot_pending.src = 'region' then 'region' else excluded.src end,
         site = excluded.site, lat = excluded.lat, lng = excluded.lng; end if;
end $function$
CREATE OR REPLACE FUNCTION public.ot_read(p_who text, p_at bigint, p_acc integer, p_open text, p_open_m integer, p_open_fence integer, p_near text, p_near_m integer, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  insert into private.ot_reads(who, at, acc, open_site, open_m, open_fence, near_site, near_m, note)
  values (p_who, to_timestamp(p_at/1000.0), p_acc, p_open, p_open_m, p_open_fence, p_near, p_near_m, left(p_note, 200));
  if random() < 0.02 then delete from private.ot_reads where at < now() - interval '14 days'; end if;
end $function$
CREATE OR REPLACE FUNCTION public.ot_report(p_day text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare me jsonb := public.my_emp_data();
begin
  if not (me->>'role' = 'owner' or (me->>'role' = 'office' and me->>'title' = 'Payroll')) then raise exception 'only the owner or Payroll'; end if;
  return jsonb_build_object(
    'people', coalesce((select jsonb_agg(jsonb_build_object('who', who, 'last', last_at, 'accepted', accepted_at, 'batt', batt, 'bs', bs, 'batt_at', batt_at, 'mode', mode, 'mode_at', mode_at, 'fix', last_tst)) from private.ot_tokens), '[]'::jsonb),
    'app', coalesce((select jsonb_agg(jsonb_build_object('who', who, 'site', site, 'at', at, 'open', open)) from private.app_seen), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(jsonb_build_object('who', who, 'at', (extract(epoch from at)*1000)::bigint, 'kind', kind, 'site', site, 'note', note) order by at)
      from private.ot_events where to_char(at at time zone 'America/New_York','YYYY-MM-DD') = p_day), '[]'::jsonb));
end $function$
CREATE OR REPLACE FUNCTION public.ot_setup(accept boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare me jsonb := public.my_emp_data(); w text := me->>'id'; r private.ot_tokens;
begin
  if w is null then raise exception 'not signed in'; end if;
  select * into r from private.ot_tokens where who = w;
  if not found then
    if not accept then return jsonb_build_object('who', w, 'on', false, 'accepted', false); end if;
    insert into private.ot_tokens(who, token, accepted_at) values (w, encode(gen_random_bytes(18), 'hex'), now()) returning * into r;
  elsif accept and r.accepted_at is null then update private.ot_tokens set accepted_at = now() where who = w returning * into r; end if;
  return jsonb_build_object('who', w, 'token', r.token, 'accepted', r.accepted_at is not null, 'last', r.last_at, 'lastKind', r.last_kind,
    'url', (select v from server_config where k = 'functions_url') || '/owntracks');
end $function$
