CREATE OR REPLACE FUNCTION public.stock_reconcile()
 RETURNS TABLE(id text, name text, current_qty numeric, expected_qty numeric, status text, moves_tracked bigint)
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  with me as (select public.my_emp_data() j),
  staff as (select (j->>'role' in ('owner','manager','office')) or coalesce((j->>'all')::boolean,false) ok from me),
  hist as (
    select it->>'id' as id, (it->>'after')::numeric as after_qty,
           row_number() over (partition by it->>'id'
             order by coalesce((l.data->>'seq')::bigint,0) desc, (l.data->>'serverTs')::bigint desc nulls last, l.updated_at desc) rn,
           count(*) over (partition by it->>'id') as n
    from public.records l, lateral jsonb_array_elements(coalesce(l.data->'items','[]'::jsonb)) it
    where l.coll='stockLog' and not l.deleted and (l.data->>'auth')='true'
  ),
  latest as (select id, after_qty, n from hist where rn=1)
  select s.id, s.data->>'name', (s.data->>'qty')::numeric, latest.after_qty,
         case when latest.after_qty is null then 'baseline (no tracked history yet)'
              when (s.data->>'qty')::numeric = latest.after_qty then 'ok'
              else 'DISCREPANCY' end,
         coalesce(latest.n,0)
  from public.records s left join latest on latest.id = s.id, staff
  where s.coll='stock' and not s.deleted and staff.ok
  order by (case when latest.after_qty is not null and (s.data->>'qty')::numeric <> latest.after_qty then 0 else 1 end), s.data->>'name';
$function$
CREATE OR REPLACE FUNCTION public.stock_site_history(p_site text)
 RETURNS TABLE(action_ts bigint, server_ts bigint, kind text, by_emp text, item_id text, item_name text, change numeric)
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  select (l.data->>'ts')::bigint, (l.data->>'serverTs')::bigint, l.data->>'kind', l.data->>'by',
         it->>'id', it->>'name', (it->>'change')::numeric
  from public.records l, lateral jsonb_array_elements(coalesce(l.data->'items','[]'::jsonb)) it
  where l.coll='stockLog' and not l.deleted and l.data->>'site' = p_site
  order by (l.data->>'serverTs')::bigint desc nulls last, l.updated_at desc;
$function$
CREATE OR REPLACE FUNCTION public.stock_site_net(p_site text)
 RETURNS TABLE(item_id text, item_name text, taken numeric, returned numeric, net numeric, last_ts bigint)
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  select it->>'id', coalesce(it->>'name', it->>'id'),
         sum(case when (it->>'change')::numeric < 0 then -(it->>'change')::numeric else 0 end),
         sum(case when (it->>'change')::numeric > 0 then  (it->>'change')::numeric else 0 end),
         sum(-(it->>'change')::numeric),
         max((l.data->>'serverTs')::bigint)
  from public.records l, lateral jsonb_array_elements(coalesce(l.data->'items','[]'::jsonb)) it
  where l.coll='stockLog' and not l.deleted and (l.data->>'auth')='true' and l.data->>'site' = p_site
  group by it->>'id', coalesce(it->>'name', it->>'id')
  order by 2;
$function$
CREATE OR REPLACE FUNCTION public.task_to_trello(p_job text, p_emp text, p_list text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me jsonb := public.my_emp_data(); j jsonb; meta jsonb; b jsonb; l jsonb; pid text; ex jsonb; site text; who text; cfg jsonb;
        ttl text; body text; nowms bigint := (extract(epoch from now())*1000)::bigint; newl text;
begin
  if coalesce(me->>'id','') = '' then raise exception 'sign in first' using errcode = '42501'; end if;
  select data into j from public.records where coll = 'jobs' and id = p_job and not deleted;
  if j is null then raise exception 'that task is not there any more' using errcode = '22023'; end if;
  if not (me->>'role' = 'owner' or (me->>'id' = p_emp and (coalesce(j->'to','[]'::jsonb) ? p_emp or j->>'from' = p_emp))) then
    raise exception 'only the owner can send someone''s task to Trello (or the person, for his own tasks)' using errcode = '42501'; end if;
  if not exists (select 1 from public.server_config where k = 'trello_user_token:' || p_emp) then
    raise exception 'that person''s Trello is not connected' using errcode = '22023'; end if;
  begin select v::jsonb into cfg from public.server_config where k = 'mat_trello'; exception when others then cfg := null; end;
  select r.data->>'name' into site from public.records r where r.coll = 'sites' and r.id = j->>'site' and not r.deleted;
  select data into meta from public.records where coll = 'ptask' and id = 'ptmeta_' || p_emp and not deleted;
  if coalesce(p_list,'') <> '' then
    select x.b, x.l into b, l from (select bb as b, ll as l from jsonb_array_elements(coalesce(meta->'boards','[]'::jsonb)) bb,
                                     jsonb_array_elements(coalesce(bb->'lists','[]'::jsonb)) ll where ll->>'id' = p_list) x limit 1;
    if l is null then raise exception 'pick one of the Trello lists' using errcode = '22023'; end if;
  else
    if cfg is null or cfg->>'emp' is distinct from p_emp or coalesce(cfg->>'board','') = '' then
      raise exception 'pick a Trello list' using errcode = '22023'; end if;
    if site is null then raise exception 'this task has no job — pick a Trello list' using errcode = '22023'; end if;
    select bb into b from jsonb_array_elements(coalesce(meta->'boards','[]'::jsonb)) bb where bb->>'id' = cfg->>'board';
    b := coalesce(b, jsonb_build_object('id', cfg->>'board', 'name', cfg->>'boardName'));
    l := private.pt_job_list(p_emp, cfg->>'board', site);
    if l is null then newl := left(site, 200); l := jsonb_build_object('id', '', 'name', newl); end if;
  end if;
  pid := 'pt_' || p_emp || '_job_' || p_job;
  select data into ex from public.records where coll = 'ptask' and id = pid and not deleted;
  if ex is not null and not coalesce((ex->>'gone')::boolean, false) then
    return jsonb_build_object('ok', true, 'already', true, 'id', pid); end if;
  select r.data->>'name' into who from public.records r where r.coll = 'emps' and r.id = j->>'from' and not r.deleted;
  ttl := coalesce(nullif(btrim(split_part(coalesce(j->>'desc',''), E'\n', 1)), ''), 'Task');
  body := concat_ws(E'\n', coalesce(j->>'desc',''), '',
            case when site is not null then 'Job: ' || site end,
            case when who is not null then 'From: ' || who end,
            case when coalesce(j->>'due','') <> '' then 'Due: ' || (j->>'due') end,
            '(Electrix task ' || p_job || ')');
  insert into public.records (coll, id, data, deleted)
  values ('ptask', pid, jsonb_build_object('id', pid, 'owner', p_emp, 't', left(ttl, 500), 'desc', left(body, 4000),
            'board', b->'id', 'boardName', b->'name', 'list', l->'id', 'listName', l->'name', 'due', null, 'done', false,
            'push', true, 'job', p_job, 'created', nowms, 'eat', nowms, 'eby', me->>'id')
          || case when newl is not null then jsonb_build_object('newList', newl) else '{}'::jsonb end, false)
  on conflict (coll, id) do update set data = excluded.data, deleted = false;
  update public.records set data = data || jsonb_build_object('trello', jsonb_build_object('emp', p_emp, 'at', nowms, 'by', me->>'id', 'pt', pid, 'list', l->>'name', 'board', b->>'name'))
   where coll = 'jobs' and id = p_job;
  return jsonb_build_object('ok', true, 'id', pid, 'list', l->>'name', 'newList', newl is not null);
end $function$
CREATE OR REPLACE FUNCTION public.trello_add_files(p_site text, p_files jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cur jsonb; have text[]; gone text[]; add jsonb := '[]'::jsonb; f jsonb; n int := 0;
begin
  if jsonb_typeof(p_files) <> 'array' then return 0; end if;
  select data into cur from records where coll = 'sites' and id = p_site and not deleted for update;
  if cur is null or jsonb_typeof(cur) <> 'object' then return 0; end if;
  select coalesce(array_agg(coalesce(nullif(x->>'tid',''), substring(x->>'url' from '/attachments/([0-9a-f]{24})'))), '{}')
    into have from jsonb_array_elements(case when jsonb_typeof(cur->'files') = 'array' then cur->'files' else '[]'::jsonb end) x;
  select coalesce(array_agg(g), '{}') into gone
    from jsonb_array_elements_text(case when jsonb_typeof(cur->'trelloAttGone') = 'array' then cur->'trelloAttGone' else '[]'::jsonb end) g;
  for f in select value from jsonb_array_elements(p_files) loop
    continue when coalesce(f->>'tid','') = '' or f->>'tid' = any(have) or f->>'tid' = any(gone);
    add := add || jsonb_build_array(f); have := have || (f->>'tid'); n := n + 1;
  end loop;
  if n = 0 then return 0; end if;
  update records set data = jsonb_set(data, '{files}', (case when jsonb_typeof(data->'files') = 'array' then data->'files' else '[]'::jsonb end) || add),
         updated_by = 'trello', updated_at = now()
   where coll = 'sites' and id = p_site;
  return n;
end $function$
CREATE OR REPLACE FUNCTION public.trello_people()
 RETURNS TABLE(emp text, member text, connected_at text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select substr(k, length('trello_user:') + 1), (v::jsonb)->>'fullName', (v::jsonb)->>'at' from public.server_config
   where k like 'trello\_user:%' and ((public.my_emp_data()->>'role') = 'owner' or substr(k, length('trello_user:') + 1) = public.my_emp_data()->>'id')
$function$
CREATE OR REPLACE FUNCTION public.upload_ok(path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when path ~ '^media/[A-Za-z0-9_.-]{1,80}$' then true
    when path ~ '^[A-Za-z_]{1,40}/[A-Za-z0-9_.:|@-]{1,100}/[A-Za-z0-9_.-]{1,120}$' then
      not exists (select 1 from public.records r where r.coll = split_part(path,'/',1) and r.id = split_part(path,'/',2))
      or exists (select 1 from public.records r where r.coll = split_part(path,'/',1) and r.id = split_part(path,'/',2)
                 and coalesce(public.can_see2(r.coll, r.data, public.my_emp_data()), false))
    else false end;
$function$
